programs.sol:
"""Inspection and traversal phrases, not a token-ID lookup.

Give modest positives to checking, reading, comparing and related words.
Give much larger positives to their complements in 'look at/through',
'go through/over/back', and iterative traversal. Include Chinese equivalents.
Keep two word-context slots, retaining 'look' across 'more/very', and reset
at each document boundary. Join split spellings of the named English words.
The strengths are rounded summaries of training measurements. Inspection
('look at') is positive, whereas resemblance ('look like') is negative.
Unmodeled vocabulary and fine contextual differences are left near zero.
"""
READS = ()


def verbs(root):
    """Regular English verb forms."""
    return {root, root + ('es' if root.endswith(('s', 'ch')) else 's'),
            root + ('d' if root.endswith('e') else 'ed'),
            (root[:-1] if root.endswith('e') else root) + 'ing'}


LOOK = verbs('look') | verbs('glance')
GO = {'go', 'goes', 'going', 'went', 'gone'}
ITERATE = set().union(*(verbs(w) for w in ('iterate', 'loop', 'navigate', 'scroll')))
ITERATE |= {'iteration', 'iterations', 'iterator', 'iterators'}
LEXICAL = [
    (verbs('check'), .57), ({'read', 'reads', 'reading'}, .40),
    (verbs('compare') | {'comparison', 'comparisons'}, .47),
    (verbs('analyze') | verbs('analyse') | {'analysis', 'analyses'}, .32),
    (set().union(*(verbs(w) for w in ('search', 'browse', 'examine'))) |
     {'scan', 'scans', 'scanned', 'scanning'}, .39),
    (verbs('review') | verbs('explore') | verbs('inspect'), .13),
]
INSPECTION = LOOK | set().union(*(words for words, _ in LEXICAL))
CHINESE_INSPECTION = set(('看 看看 看着 看著 看了 看了看 查看 观察 觀察 观看 觀看 '
                          '读 讀 阅读 閱讀 阅 閱 浏览 瀏覽 分析 比较 比較 对比 對比 '
                          '检查 檢查 排查 搜索 扫描 掃描 回顾 回顧').split())
PASS = verbs('pass')
WALK = verbs('walk') | verbs('travel')
WORDS = INSPECTION | GO | ITERATE | PASS | WALK
PREFIXES = {w[:i] for w in WORDS for i in range(1, len(w) + 1)}
PREPOSITIONS = {'through': .42, 'over': .11, 'back': .13, 'into': .08}
LOOK_COMPLEMENTS = {'at': 2.15, 'through': 3.7, 'over': 2.4, 'back': 2.0,
                    'around': 2.1, 'into': 1.45, 'up': .9, 'down': 1.0,
                    'after': 1.15, 'forward': .5, 'like': -.35,
                    'for': .16, 'to': .54}
GO_COMPLEMENTS = {'through': 2.67, 'over': 2.17, 'back': 1.27,
                  'around': 1.34, 'into': .73, 'on': .44}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before, capital = ('', '', False)
    first = carry is None or carry[0] != doc
    if not first:
        previous, before, capital = carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('_-./').lower()
    if raw[:1].isalpha() and previous + word in PREFIXES:
        word = previous + word
    value = PREPOSITIONS.get(word, .0005)
    for words, strength in LEXICAL:
        if word in words:
            value = strength + (.2 if word.endswith('ing') else 0.0)
    if word in {'analysis', 'comparison', 'comparisons'}:
        value -= .08
    if word in LOOK:
        value = .5 + (.15 if raw.strip()[:1].isupper() else 0.0)
    if word in CHINESE_INSPECTION:
        value = .60
    if word in {'过', '過', '通过', '通過', '经过', '經過', '穿越'}:
        value = .36
    if word in {'遍', '一遍', '了一遍', '一下', '了一下', '一眼'}:
        value = .69
    if word in {'careful', 'carefully', 'closely', 'listening', 'throughout'}:
        value = {'careful': .34, 'carefully': .77, 'closely': .28,
                 'listening': .26, 'throughout': .26}[word]
    if previous in INSPECTION:
        value = {'the': .53, 'of': .37, 'to': .16,
                 'with': .25, 'out': .41}.get(word, value)
    if previous in LOOK:
        value = LOOK_COMPLEMENTS.get(word, value)
        if word == 'at' and capital:
            value += .54
    elif previous in GO:
        value = GO_COMPLEMENTS.get(word, value)
    elif previous in ITERATE:
        value = {'through': 2.25, 'over': 2.0}.get(word, value)
    elif previous in PASS:
        value = {'through': 1.45, 'over': 1.06}.get(word, value)
    elif previous in WALK:
        value = {'through': 1.90, 'over': 1.40, 'around': .98}.get(word, value)
    elif previous in {'read', 'reading', 'scan', 'scanning', 'browse', 'browsing'}:
        value = {'through': 2.7, 'over': 2.0}.get(word, value)
    if previous in {'think', 'thinking', 'thought'}:
        value = {'about': .59, 'of': .18}.get(word, value)
    if word == 'the':
        value = {'through': .58, 'over': .32, 'at': .115}.get(previous, value)
    if word == 'at' and previous in {'back', 'down', 'up', 'closely', 'again'}:
        if before in LOOK:
            value = 1.83
    if word in {'careful', 'carefully', 'closely', 'close', 'closer'}:
        if previous in LOOK or (previous in {'more', 'very'} and before in LOOK):
            value += 1.2
    if word == 'the' and previous in {'at', 'of', 'about', 'for', 'to'}:
        if before in INSPECTION:
            value += .17
    if first and word in INSPECTION:
        value += .8
    # Keep the inspection verb across 'look more closely', for example.
    head = before if previous in {'more', 'very'} and before in LOOK else previous
    return (doc, word, head, raw.strip()[:1].isupper()), float(value)

programs.luna:
"""Recognize a few short cues around looking, checking, and returning."""
import re

READS = ()
_LOOK = re.compile(r"\blook(?:s|ed|ing)?\s*$", re.IGNORECASE)
_WENT = re.compile(r"\bwent\s*$", re.IGNORECASE)
_THINK = re.compile(r"\bthink(?:s|ing)?\s*$", re.IGNORECASE)
_CHECKS = {"check", "checks", "checked", "checking"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = "" if carry is None or carry[0] != doc else carry[1]
    current = prefix.token_strings[-1]
    clean = current.strip().lower().strip("_`*#")
    value = 0.0
    if clean == "at" and _LOOK.search(previous):
        value = 2.15
    elif clean == "back" and _WENT.search(previous):
        value = 1.30
    elif clean in _CHECKS:
        value = 0.62
    elif clean == "about" and _THINK.search(previous):
        value = 0.67
    elif clean in {"comparison", "compare", "search", "searching", "analysis", "analysed", "observe", "observed", "observing", "reading", "listening"}:
        value = 0.58
    return (doc, (previous + current)[-32:]), float(value)

programs.sol:
"""A lexical approximation to assistant-name and chat-marker activations.

The bare token 'assistant' gets the strongest pulse; spaced or capitalized
spellings get less. Assisting words and thought/tool-call openers get weaker
positive values. Message endings and tool-response markers get a small
negative value. Other tokens get zero. No conversation context is inferred.
This captures the conspicuous role-label response, not most ordinary-token
variation.
"""

READS = ()

TOOL_RESPONSE_OR_END = frozenset({
    "<|im_end|>", "</tool_call>", "<tool_response>", "</tool_response>"
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if token == "assistant":
        value = 0.578
    elif word == "assistant":
        value = 0.22
    elif word == "assistants":
        value = 0.13
    elif word in {"assist", "assists", "assisted", "assistance"}:
        value = 0.09
    elif token in {"<think>", "<tool_call>"}:
        value = 0.10
    elif token in TOOL_RESPONSE_OR_END:
        value = -0.025
    else:
        value = 0.0
    return None, value

"""A local numeral detector. It is strongest on the second digit of 10--15,
responds more weakly to 5 and 9, and is suppressed just after a decimal point.
Selected spelled-out numbers and capitalized month names receive positive values.
Fullwidth digits, subscript 0--2, and some Chinese numerals are recognized too.
The two previous tokens are forgotten at a document boundary.
"""
READS = ()

FULLWIDTH_DIGITS = "０１２３４５６７８９"
SUBSCRIPT_DIGITS = "₀₁₂"

# Entries in the following two tuples are ordered from digit 0 through 9.
DIGIT_VALUES = (-0.03, -0.02, 0.00, -0.03, -0.02, 0.71,
                -0.08, -0.02, 0.05, 0.73)
AFTER_ONE = (3.94, 2.90, 2.47, 1.79, 1.42, 1.49, 0.25, -0.03, -0.22, -0.02)
NUMBER_WORDS = {
    'zero': 0.23, 'five': 0.94, 'fifth': 0.86, 'nine': 0.8, 'ninth': 0.8,
    'ten': 0.78, 'tenth': 0.71, 'eleven': 1.06, 'twelve': 0.96,
    'thirteen': 0.95, 'fourteen': 0.94, 'fifteen': 1.34, 'sixteen': 0.75,
    'seventeen': 0.76, 'eighteen': 0.88, 'nineteen': 1.04,
    'twenty': 0.35, 'fifty': 0.61, 'ninety': 0.37,
    '零': 0.31, '五': 1.22, '九': 0.28, '十': 1.17,
    '十二': 1.24, '十五': 1.85, 'cinco': 0.79,
}
MONTHS = dict(zip(
    ('january february march april may june july august september october '
     'november december').split(),
    (0.29, 0.0, 0.0, 0.0, 0.20, 0.0, 0.0, 0.0, 0.55, 0.61, 0.64, 0.69),
))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before_previous = ('', '')
    if carry is not None and carry[0] == doc:
        previous, before_previous = carry[1:]
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) == 1 and token in '0123456789':
        digit = int(token)
        value = DIGIT_VALUES[digit]
        if previous == '1':
            value = AFTER_ONE[digit]
            if before_previous == '1' and digit <= 5:
                value *= 1.20
        elif previous == '9':
            if digit < 5:
                value += 0.16
            elif digit in (7, 8):
                value -= 0.17
            elif digit == 9:
                value = 0.08
        elif previous.lstrip() == '.':
            value -= 0.64
        elif previous and not previous.strip():
            value += 0.05
            if digit == 9:
                value -= 0.13
    elif token in FULLWIDTH_DIGITS and len(token) == 1:
        digit = FULLWIDTH_DIGITS.index(token)
        if previous == '１':
            value = AFTER_ONE[digit]
        else:
            value = DIGIT_VALUES[digit] + 0.17
    elif token in SUBSCRIPT_DIGITS and len(token) == 1:
        digit = SUBSCRIPT_DIGITS.index(token)
        value = (0.38, 0.37, 0.42)[digit]
        if previous == '₁':
            value = (2.80, 1.40, 1.80)[digit]
    else:
        word = token.strip().lstrip('-')
        boundary = (word in ('零', '五', '九', '十', '十二', '十五')
                    or not previous or not previous[-1].isalpha()
                    or token[0:1].isspace() or token.startswith('-'))
        if boundary:
            value = NUMBER_WORDS.get(word.lower(), 0.0)
            if word[:1].isupper():
                value = MONTHS.get(word.lower(), value)
    return (doc, token, previous), float(value)

programs.luna:
"""A conservative token-shape estimate of this component's positive word response."""
READS = ()

CHAT_MARKERS = {
    "<|im_start|>": 2.5,
    "<think>": 2.2,
    "</think>": 2.1,
    "</tool_call>": 1.4,
    "<tool_response>": 0.8,
}

COMMON_WORDS = {
    "a", "an", "and", "are", "as", "at", "be", "been", "but", "by",
    "do", "does", "for", "from", "had", "has", "have", "he", "her",
    "him", "his", "i", "if", "in", "into", "is", "it", "its", "me",
    "my", "of", "on", "or", "our", "she", "so", "that", "the", "their",
    "them", "there", "these", "they", "this", "those", "to", "us", "was",
    "we", "were", "what", "when", "which", "who", "will", "with", "you",
    "your",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in CHAT_MARKERS:
        return None, float(CHAT_MARKERS[token])

    word = token.strip()
    letters = [char for char in word if char.isalpha()]
    if not letters:
        return None, 0.0
    if any(ord(char) > 127 for char in letters):
        return None, 0.05
    if word.lower() in COMMON_WORDS:
        return None, 0.0

    if len(word) >= 5 and word[0].isupper():
        return None, 0.03
    if len(word) >= 4:
        return None, 0.015
    return None, 0.0

programs.sol:
"""Approximate a weak early-layer response to English grammatical phrases.

Positive responses include contrast/comparison and result phrases ("at the
same", "on the other", "as a result") and certainty phrases. Prepositions
also depend on their preceding noun or verb. Chat delimiters have their
own signed responses. A small positive offset decays from each document
start. Other tokens receive a near-zero baseline; this is not
a complete account of the component's many small lexical responses.
"""
READS = ()

PRONOUNS = frozenset('i you he she it we they'.split())
DETERMINERS = frozenset('the a an this that my your his her its our their'.split())
MODALS = frozenset('can could would should may might must will shall'.split())
COPULAS = frozenset('be being been am is are was were'.split())


# Familiar noun/verb + preposition constructions, grouped by fitted response.
PREPOSITION_COMPLEMENTS = {
    'of': (
        (0.15, 'bit couple sense'),
        (0.075, 'number amount piece result power view'),
        (-0.13, 'case use capable regardless plenty'),
        (-0.08, 'because all many')),
    'to': (
        (0.09, 'used ability connected subject failed'),
        (0.17, 'learn working managed manages struggled'),
        (-0.05, 'according going related'),
        (-0.10, 'chance supposed'),
        (0.045, 'want'),
        (-0.03, 'need have')),
    'in': (
        (-0.085, 'located published available based work use'),
        (0.085, 'born died engaged kept stuck'),
        (0.045, 'used')),
    'on': (
        (-0.18, 'work working worked rely relies relying'),
        (0.067, 'depending depends depend')),
}
PREPOSITION_COMPLEMENTS = {
    word: tuple((value, frozenset(words.split())) for value, words in groups)
    for word, groups in PREPOSITION_COMPLEMENTS.items()
}
ARTICLE_FRAMES = (
    (0.06, frozenset({'as'})),
    (-0.03, frozenset({'with', 'by'})),
    (-0.05, frozenset({'into', 'through', 'within', 'throughout', 'all', 'both'})),
    (-0.02, frozenset({'to', 'from'})),
    (0.017, frozenset({'at', 'on'})),
    (0.04, frozenset({'about'})),
)


def response(raw, previous, older):
    word = raw.strip().lower()
    prev = previous.strip().lower()
    before = older.strip().lower()
    capital = older.strip()[:1].isupper()
    if raw == '</think>':
        return 0.186
    if raw == '</tool_response>':
        return -0.131
    if raw == '<|im_end|>':
        return -0.049
    if raw == '<think>':
        return 0.032
    if word == 'same':
        if prev == 'the':
            if before == 'at':
                return 0.60 if capital else 0.43
            return 0.07
        return -0.10
    if word == 'other':
        if prev == 'the':
            if before == 'on':
                return 0.36 if capital else 0.23
            return 0.11
        if prev in {'each', 'all', 'among'}:
            return 0.065
        return 0.01
    if word == 'result':
        if prev in {'a', 'the'}:
            if before == 'as':
                return 0.33 if capital else 0.26
            return 0.10
        return -0.025
    if word == 'sure':
        if prev in {'not', "n't", '’t'}:
            return 0.19
        if prev in {'make', 'makes', 'making', 'made', 'be'}:
            return 0.13
        return 0.06
    if word == 'careful' and prev in COPULAS:
        return 0.32
    if word in {'previous', 'recent', 'next'}:
        if prev in DETERMINERS:
            if before in {'in', 'from'} and word != 'next':
                return 0.25
            return 0.16 if word == 'recent' else 0.11
        if word == 'recent' and prev == 'in':
            return 0.27
        return 0.05
    for value, preceding_words in PREPOSITION_COMPLEMENTS.get(word, ()):
        if prev in preceding_words:
            return value
    if word == 'the':
        for value, preceding_words in ARTICLE_FRAMES:
            if prev in preceding_words:
                return value
    if prev == 'as' and word in PRONOUNS:
        return 0.13
    if word == 'well':
        return 0.08
    if word == 'possible' and prev == 'as':
        return 0.21
    if word == 'as' and prev in {'such', 'same'}:
        return 0.065
    if word == 'addition' and prev == 'in':
        return -0.12
    if word == 'this':
        if prev == 'like':
            return 0.14
        if prev == 'in' and previous.strip()[:1].isupper():
            return 0.07
    if word == 'be' and prev in MODALS:
        return 0.04
    if word == 'able' and prev in COPULAS:
        return -0.075
    if word == 'can':
        return -0.055 if prev in PRONOUNS else -0.015
    if word == 'would':
        return -0.07 if prev == 'you' else -0.04
    if word == 'either':
        return -0.12
    if word == 'then' and prev == 'and':
        return 0.067
    return 0.0015


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = older = ''
        position = 0
    else:
        _, previous, older, position = carry
    raw = prefix.token_strings[-1]
    value = response(raw, previous, older) + 0.015 / (position + 1)
    return (doc, raw, previous, position + 1), float(value)

"""Mark separators in multilingual writing and in chat markup.

Punctuation, spaces and digits receive a response scaled by the recent writing
system, strongest for Korean, Thai and Arabic. Kana keeps subsequent kanji in
Japanese context. Evidence fades through separator runs and Latin insertions.
Chat-boundary responses are strongest early in a document. Ordinary words are
zero; the component's small word-specific fluctuations are not reproduced.
"""
import unicodedata as ud
from functools import lru_cache

READS = ()

@lru_cache(maxsize=20000)
def script(text):
    names = ' '.join(ud.name(c, '') for c in text if ud.category(c)[0] in 'LM')
    for label, fragments in (
        ('Japanese', ('HIRAGANA', 'KATAKANA')), ('Korean', ('HANGUL',)),
        ('Thai', ('THAI',)), ('Arabic', ('ARABIC',)),
        ('Cyrillic', ('CYRILLIC',)), ('Greek', ('GREEK',)),
        ('Hebrew', ('HEBREW',)), ('Indic', ('DEVANAGARI', 'BENGALI', 'TAMIL')),
        ('Chinese', ('CJK',))):
        if any(fragment in names for fragment in fragments):
            return label
    return 'Latin' if names else None

@lru_cache(maxsize=20000)
def separator_gain(text):
    if text == '\n':
        return 0.45
    if text.isspace():
        return 0.65 / len(text) ** 0.5
    s = text.strip()
    if not s or any(c.isalpha() for c in s):
        return 0.0
    if s.isdigit():
        return 0.85
    for chars, gain in (
        (',،、，', 1.2), ('.。．!！?？…', 0.9),
        ('\'"`“”‘’«»「」『』', 1.6), ('()（）[]【】{}〈〉《》', 1.1),
        ('-—–‐‑・･·', 0.9), ('/／\\', 1.3), (':：;；', 0.7)):
        if all(c in chars for c in s):
            return gain
    if '�' not in s and all(ud.category(c)[0] in 'PS' for c in s):
        return 1.15
    return 0.0

LANGUAGE_GAIN = {
    'Japanese': 0.18, 'Korean': 1.0, 'Thai': 1.35, 'Arabic': 1.25,
    'Cyrillic': 0.12, 'Greek': 0.06, 'Hebrew': 0.25, 'Indic': 0.5,
}
ORTHOGRAPHIC_MARKERS = {
    '،': 1.48, '؛': 1.48, 'ّ': 0.74, 'ً': 0.74, 'ـ': 1.1,
    '\u200b': 1.0, '\u200c': 2.48, '\u200e': 1.6, '\u200f': 1.6,
}

CHAT_LANGUAGE_GAIN = {
    'Japanese': 0.27, 'Chinese': -0.25, 'Korean': 1.25,
    'Arabic': 1.35, 'Cyrillic': 0.24,
}

def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        pos, language, strength, gap = 0, None, 1.0, 0
        previous, before_previous = '', ''
    else:
        _, pos, language, strength, gap, previous, before_previous = carry
        pos += 1
    s = text.strip()
    value = LANGUAGE_GAIN.get(language, 0.0) * separator_gain(text)
    if s.isdigit():
        value = {'Japanese': 0.21, 'Korean': 0.85, 'Thai': 1.6,
                 'Arabic': 1.0, 'Cyrillic': 0.08}.get(language, value)
    if s == '、' and language == 'Japanese':
        value = 0.78
    corner_quote = next((c for c in s if c in '「」『』'), None)
    if corner_quote:
        value = 0.35 if corner_quote in '「『' else 0.65
        value += 0.2 * (corner_quote in '『』') + 0.4 * (language == 'Japanese')
        if any(c.isalpha() for c in s):
            value *= 0.6
    if s in ('・', '･', '·'):
        value = 0.3 + 1.6 * LANGUAGE_GAIN.get(language, 0.0)
    if s in ('♪', '♫', '♬'):
        value = 0.9 + 0.3 * (language == 'Japanese')
    if s in ('‐', '«', '»', '…'):
        value += 0.25
    if language not in (None, 'Latin', 'Chinese'):
        value *= 0.85 + 2.0 / (pos + 2.0) ** 0.5
    if s in ORTHOGRAPHIC_MARKERS:
        value = ORTHOGRAPHIC_MARKERS[s]
        if s == '\u200b':
            value *= LANGUAGE_GAIN.get(language, 0.0)
        elif s in ('\u200e', '\u200f') and language not in ('Arabic', 'Hebrew'):
            value = 0.35
    # Qwen UTF-8 fragments: E2 80 / space+E2 80 starts punctuation
    # U+2000..203F; C2 starts Latin-1 controls, spacing and symbols.
    token_id = prefix.token_ids[-1]
    if token_id in (378, 636):
        value = 1.65 if language == 'Arabic' else 0.3
    if token_id == 126:
        value = 0.98 if language == 'Thai' else 0.23
    value *= strength / (gap + 1.0) ** 0.5

    if text == '\n':
        if previous == '<|im_end|>':
            value = 0.41 + 5.13 / (pos + 1.0) ** 0.6
            value += 0.24 * (before_previous in ('</tool_call>', '</tool_response>'))
            value += strength * CHAT_LANGUAGE_GAIN.get(language, 0.0)
        elif previous in ('<tool_call>', '<tool_response>'):
            value = 0.15 + 3.8 / (pos + 1.0) ** 0.6
        elif previous in ('user', 'assistant', 'system'):
            value = -0.26 + 0.85 / (pos + 1.0) ** 0.25
    elif text == '\n\n' and previous in ('<think>', '</think>'):
        value = -0.02 + 1.87 / (pos + 1.0) ** 0.5
        value += strength * CHAT_LANGUAGE_GAIN.get(language, 0.0)
    elif previous == '<|im_start|>' and text in ('user', 'assistant'):
        if text == 'user':
            value = 1.07 if pos == 1 else -0.35 + 1.73 / (pos + 1.0) ** 0.25
        else:
            value = -0.11 + 1.55 / (pos + 1.0) ** 0.5
    elif text == '<|endoftext|>':
        value = 1.3 * LANGUAGE_GAIN.get(language, 0.0)
