programs.haiku:
"""Layer-0 MLP unit 3337 (down_proj), as a short list of readable triggers.

The unit writes into the residual stream when the MLP sees one of a few kinds of
token. Each trigger has a typical strength (activation units; 0 means silent):

  * the newline that ends a chat turn (right after <|im_end|>, about 0.9), and a
    newline right after <tool_call>, <tool_response> or </think> (0.4 to 0.5);
  * the role word "user" that opens a chat turn: about 1.0 when the turn starts a
    document (or follows <|endoftext|>), weak (0.2) when it comes mid-document;
  * Japanese punctuation: the ideographic comma 、 (0.8 after kana, weak after
    kanji), the corner brackets 「」『』 and the middle dot ・;
  * Arabic punctuation and vowel marks (،, harakat, tatweel, about 0.9), and
    invisible format characters such as the zero-width non-joiner (about 2);
  * the lone byte 0xC2 (token 126), which starts a 2-byte UTF-8 character
    (nbsp, ©, «, °) and shows up alone as a replacement character (0.9);
  * ASCII punctuation and digits inside text of Arabic, Hangul (Korean), Thai,
    Telugu or Tamil script: the strength equals the share of the recent
    characters (last 12 tokens) that are in those scripts, so 0 in Latin text
    and about 1 deep inside such a passage.

Everything else is predicted as 0. The values are rough averages of the activation
in each case on sampled training text, not fitted constants.
"""
import unicodedata

READS = ()

LONE_C2_TOKEN = 126  # the single byte 0xC2 (lead byte of U+0080-U+00BF)
TAG_NEWLINE = {"<tool_call>": 0.4, "<tool_response>": 0.5, "</think>": 0.4}
BRACKETS = {"「": 0.4, "」": 0.9, "『": 0.7, "』": 1.0, "・": 0.7}
FOREIGN = ("ARABIC", "HANGUL", "THAI", "TELUGU", "TAMIL")


def foreign_share(strings):
    """The share of the non-space characters that belong to a foreign script (FOREIGN)."""
    chars = [ch for s in strings for ch in s if not ch.isspace()]
    if not chars:
        return 0.0
    hits = sum(any(key in unicodedata.name(ch, "") for key in FOREIGN) for ch in chars)
    return hits / len(chars)


def token_back(prefix, back):
    """The token `back` steps before the newest one, or "" if it is in an earlier document."""
    i = len(prefix) - 1 - back
    if i < 0 or prefix.document_ids[i] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[i]


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = token_back(prefix, 1)
    if tok == "\n" and prev == "<|im_end|>":
        return None, 0.9  # newline ending a chat turn
    if tok == "\n" and prev in TAG_NEWLINE:
        return None, TAG_NEWLINE[prev]
    if tok == "user" and prev == "<|im_start|>":
        # the role word: strong when its turn opens a document, weak mid-document
        opens_doc = token_back(prefix, 2) in ("", "<|endoftext|>")
        return None, 1.0 if opens_doc else 0.2
    if tok in BRACKETS:
        return None, BRACKETS[tok]
    if tok == "、":
        # ideographic comma: strong after kana, weak after kanji or digits
        kana = prev != "" and unicodedata.name(prev[-1], "").startswith("HIRAGANA")
        return None, 0.8 if kana else 0.15
    if prefix.token_ids[-1] == LONE_C2_TOKEN:
        return None, 0.9
    if tok and unicodedata.category(tok[0]) == "Cf":
        return None, 2.0  # invisible format characters, e.g. zero-width non-joiner
    if tok and unicodedata.name(tok[0], "").startswith("ARABIC") and unicodedata.category(tok[0]) in ("Po", "Mn", "Lm"):
        return None, 0.9  # Arabic comma, semicolon, vowel marks, tatweel
    if tok.isascii() and not tok.isalpha() and tok.strip():
        # punctuation or digit: strength = share of foreign-script characters just before it
        return None, foreign_share(prefix.token_strings[-12:])
    return None, 0.0

