        return None, 1.25 if boundary else 3.1
    if word == 'issing':
        return None, 4.8 if previous.endswith('m') else 3.2
    if word in {'issa', 'isse', 'isses', 'isser', 'issant', 'issy'}:
        return None, 1.2
    if word.startswith('miss') and boundary:
        return None, 1.0
    if word in {'kiss', 'kisses'}:
        return None, 1.1
