        value = 0.84 if raw == ' with' else 1.1
        if previous.strip() in {
                'associated', 'coincided', 'coincides', 'coinciding'}:
            value = 0.15
        elif previous.strip() in {
                'along', 'filled', 'replaced', 'compared', 'correlated'}:
            value = 0.35
        return None, value
    if word == 'without':
        return None, 0.36
    if word == 'within':
        return None, 0.1
    if word in WITH_TRANSLATIONS:
        return None, 0.5 if word in {'avec', 'với'} else 0.22
    if word in LACK_WORDS:
        return None, 0.65
    if word == 'deficient':
        return None, 0.95
    if word in {'skip', 'skips', 'skipped', 'skipping', 'omit', 'omitted'}:
        return None, 0.5
