"""Layer-0 MLP down-projection, component 3338: a "missing / lacking" word detector.

The component reads the current token only (no context is needed) and writes a large
value into the residual stream when that token spells the word "miss" in one of its forms
("miss", "Miss", " missing", " missed", "misses"), or is the "iss" piece such a word is split
into. Weaker responses go to words of lacking and absence (lack, shortage, absence,
deficiency, skip, omitted, Chinese 缺 / 缺乏 "lack"), to "with" (about 0.85 on " with", a bit
more on "With"), and to "without" (about 0.35). Every other token is predicted as 0.

Main program: the rule below. Predicted activation per token, in the component's own units.
"""

READS = ()

# Whole words that mean lacking or absent (matched after lower-casing, leading space removed).
LACK_WORDS = {
    "lack", "lacks", "lacking", "shortage", "shortages", "deficiency", "deficiencies",
    "deficient", "absence", "absent", "insufficient", "incomplete", "skip", "skipped",
    "skipping", "skips", "omitted", "lost", "disappeared", "disappearance",
}
# Chinese words for lack / deficiency.
LACK_CHARS = {"缺", "缺乏", "欠", "乏", "亏"}
# Pieces of "miss" that are not the word itself, e.g. "m" + "issing", "W" + "iss" + "ensch".
MISS_PIECES = {"iss", "isse", "issa", "isses", "isser", "issy", "issant"}


def _word(token: str) -> str:
    """The token as a lower-case word: leading space, underscore or punctuation removed."""
    return token.strip().lower().lstrip("_-(.")


def activation(token: str) -> float:
    w = _word(token)
    if w.startswith("miss") and w not in {"mission", "missions"}:
        return 5.5  # miss, missing, missed, Missouri, ...
    if w == "issing":
        return 5.3
    if w in MISS_PIECES:
        return 2.5
    if w == "with":
        return 0.85 if token == " with" else 1.1
    if w == "without":
        return 0.35
    if w in LACK_WORDS or token.strip() in LACK_CHARS:
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    # Token-only rule: the carry is not needed.
    return carry, float(activation(prefix.token_strings[prefix.position]))

