"""A local detector for the ends of short delimited spans.

Standalone closing quotes and backticks give the largest responses; brackets
and math dollars also respond. Nearby opening marks, short span length, and
CJK lettering strengthen the prediction. Whitespace, programming syntax and
escapes weaken it. Conservative exceptions avoid some primed-letter and
code-fence false alarms. Only recent marks are remembered, not balanced nesting.
"""
from math import exp
import re

READS: tuple[str, ...] = ()
PAIRS = {')': '(', ']': '[', '}': '{', '）': '（', '】': '【',
         '”': '“', '’': '‘', '》': '《', '」': '「', '』': '『', '»': '«', '“': '„'}
QUOTES = set('\"\'`”’》」』»“') | {'``'}
ALIASES = {'"': ('"', '“', '„'), '”': ('“', '„', '"'),
           "'": ("'", '‘', '`'), ')': ('(', '（'), '）': ('（', '(')}
OPENERS = set(PAIRS.values()) | set('\"\'`$')
CONTROL = {'if', 'while', 'for', 'switch', 'catch', 'func'}
STRING_PREFIX = {'f', 'r', 'b', 'u', 'fr', 'rf'}


def cjk(c):
    return bool(c) and ('\u3400' <= c <= '\u9fff' or
                       '\u3040' <= c <= '\u30ff' or '\uac00' <= c <= '\ud7af')


def response(mark, record, t, left, previous, escape):
    """Calibrated strengths for the different kinds of closing marks."""
    old, tight, syntax, bare = record
    n = t - old
    # Short spans peak around two tokens between opening and closing marks.
    near = exp(-max(0, n - 3) / 10)
    near *= 0.85 if n == 2 else (0.2 if n < 2 else 1.0)
    if mark in QUOTES:
        amplitude = 1.55 if mark == "'" else (2.1 if mark == '`' else 1.9)
        if mark == '``':
            amplitude = 0.8
        if cjk(left):
            amplitude = 2.5
        value = amplitude * near
        # A bare apostrophe after one capital letter can be a prime, not a quote.
        word = previous.strip()
        if mark == "'" and bare and word.isupper() and len(word) == 1:
            return 0.0
        if mark in {'"', "'"} and (
                tight or previous.strip().lower() in STRING_PREFIX):
            return 0.0
        value *= 0.3 if syntax else 1.0
        value *= 0.25 if escape > old else 1.0
        value *= 0.65 if bare and mark == '`' else 1.0
        if left.isdigit() and mark in {'"', '”'}:
            value *= 0.5
        elif not left.isalnum() and left not in '_)]}':
            value *= 0.4
        return value if n < 200 else (0.2 if mark in PAIRS else 0.0)
    if mark in {'$', '$$'}:
        if tight or left == '\\':
            return 0.1
        value = 1.0 + 0.7 * near if mark == '$' else 0.55 + 0.55 * near
        value *= 0.85 if left.isdigit() else 1.0
        return value * (0.6 if n > 200 else 1.0)
    broad = exp(-max(0, n - 3) / 30)
    if mark == ')':
        if tight:
            value = 0.15 + 0.25 * exp(-max(0, n - 3) / 10)
        else:
            penalty = (0.75 if n == 2 else 0.15) if n < 3 else 1.0
            value = 0.1 + 0.7 * broad * penalty
        if previous.strip().isupper() and len(previous.strip()) > 1:
            value += 0.25 * broad
        value *= 0.2 if syntax else 1.0
    elif mark == ']':
        value = 0.15 + (0.52 if left.isdigit() else 0.3) * broad
        value *= 0.8 if tight else 1.0
    elif mark == '}':
        value = 0.1 + 0.42 * broad
    else:
        value = 0.25 + (0.6 if mark == '）' else 0.25) * broad
    return value * (0.5 if n > 200 else 1.0)


def step(carry, prefix, upstream):
    doc, t = prefix.document_ids[-1], prefix.position
    if carry is None or carry[0] != doc:
        recent, previous, escape = {}, '', -10000
    else:
        _, recent, previous, escape = carry
    token, left = prefix.token_strings[-1], previous[-1:]
    if left == '\ufffd' and t:
        left = prefix.text_prefixes[-2][-1:]
    mark, fused = token.lstrip(' '), 1.0
    if token[:1] in '”》」』»' and len(token) > 1 and token[1:].isalpha():
        mark, fused = token[0], 0.55
    value = 0.0
    if mark in PAIRS or mark in QUOTES or mark in {'$', '$$'}:
        opener = PAIRS.get(mark, mark[0])
        record = max(recent.get(c, (-10000, False, False, False))
                     for c in ALIASES.get(mark, (opener,)))
        value = response(mark, record, t, left, previous, escape) * fused
        if not left or left.isspace() or token.startswith(' '):
            value *= 0.65 if mark in PAIRS and left and not left.isspace() else 0.0
    elif token.endswith('$') and token[:-1] and set(token[:-1]) <= set(')]}*'):
        value = 0.95
    elif token == '()`' or (token.endswith('`') and token[:-1]
                            and set(token[:-1]) <= set(')]}>"')):
        old, _, syntax, _ = recent.get('`', (-10000, False, False, False))
        # Do not mistake a code-fence fragment for the end of inline code.
        value = 1.0 if t - old < 80 and not syntax else 0.0
    elif token in {'}}', ')}', '})'}:
        value = 0.26
    elif token == '>':
        value = 0.18 if left.isalpha() else 0.0
    for i, char in enumerate(token):
        if char in OPENERS:
            before = token[i - 1] if i else left
            tight = bool(before and (before.isalnum() or before in '_\\'))
            if cjk(before) and char in {'"', "'", '$'}:
                tight = False
            word = re.search(r'(\w+)\s*$', previous + token[:i])
            syntax = bool(before and before in '=([,:')
            if char == '(':
                syntax = bool(word and word[1] in CONTROL)
            if char == '$' and token[i + 1:i + 2] == '_':
                tight = False
            if char == '`' and '```' in token:
                syntax = True
            recent[char] = (t, tight, syntax, token == char)
    if '\\' in token:
        escape = t
    return (doc, recent, token, escape), float(value)

