    word = token.strip()
    if word == "走":
        return -6.6
    if word == "走了":
        return -5.5
    if "走" in token:
        return -2.5
    if "walk" in token.lower():
        return -1.5
    if word in ("跑", "穿"):
        return -1.0
    if word.lower() in ("away", "gone", "moving"):
        return -0.3
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(_value(prefix.token_strings[-1]))

