FOCUS = {'focus', 'focuses', 'focused', 'focusing'}
FUNCTION_WORDS = set('''
    in at after before for to from with by of under over into through
    is are was were be been being will would can could shall should
    may might must do does did have has had and or but if as than
    that which who we you they it he she my your his her our their
    not all so ever like this these those some such both no something
    why yet exactly
'''.split())
ABSTRACT_HEADS = set('''
    problem question process case concept relationship difference possibility
'''.split())
NUMBERS = set('two three four five six seven eight nine ten'.split())
POSSESSIVES = {'my', 'your', 'his', 'her', 'our', 'their'}
START_THE = {' the': 4.82, 'The': 3.69, ' The': 3.16, 'the': 2.92}


def lexical(token, previous):
    word = token.strip()
    lower = word.lower()
    prev_word = previous.strip().lower()
    if lower == 'on':
        if prev_word in DEPENDENCE:
            return 0.01
        if prev_word in FOCUS:
            return 0.22
        if word == 'On':
            return 1.5
        if word == 'ON':
            return 0.82 if token[:1].isspace() else 0.24
        if token[:1].isspace():
            return 1.03
        return 0.15 if previous and previous[-1].isalnum() else 1.0
    # Also recognize hyphenated 'on' and camel-case event-handler prefixes.
    if re.fullmatch(r'[._(\-]?(?:on|On)(?:[A-Z][a-zA-Z]*)?', word):
        return 1.25
    if lower == 'how':
        return 0.48 if prev_word in {'see', 'understand', 'explain'} else 0.61
    return 0.59 if lower == 'onto' else 0.0


def after_the(token, ordinary):
    word = token.strip()
    lower = word.lower()
    if not word:
        return 0.61
    if word.isascii() and word.isalpha() and not token[:1].isspace():
        return 2.0 if len(word) == 1 else 1.3
    if lower in {'one', 'ones', 'only'}:
        return 1.35
    if lower == 'the':
        return 3.49
    if lower in {'a', 'an'}:
        return 2.6 if word.islower() else 0.7
    if lower in {'many', 'much'}:
        return 1.1
    if lower in FUNCTION_WORDS:
        return 1.65 if word.islower() else 0.5
    if lower in ABSTRACT_HEADS or lower == 'top':
        return -0.51
    if lower in NUMBERS or lower == 'number':
        return -0.26 if lower in NUMBERS else -0.33
    if lower in {'following', 'same', 'other', 'first'}:
        return -0.22
    if lower == 'on':
        return 2.37
    if len(word) == 1 and word.isascii() and word.isalpha():
        return 0.8 if word.islower() else 0.2
    if not any(c.isalnum() for c in word):
        return 0.65
    return ordinary


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    lower = token.strip().lower()
    value = lexical(token, previous)
    if previous.strip().lower() == 'the':
        value = after_the(token, value)
    if first:
        if lower == 'the':
            value = START_THE.get(token, 2.92)
        elif lower in {'a', 'an'}:
            value = 0.79 if token[:1].isspace() and token.islower() else 0.25
        elif lower in POSSESSIVES:
            value = 1.1
        elif lower in {'this', 'these', 'some', 'each'}:
            value = 0.55
        elif lower == 'on':
            value += 0.8
        elif lower == 'how':
            value = 0.94
    return (doc, token), float(value)

