"""Layer-0 MLP neuron 3349 (down_proj): a detector for the preposition "on".

Mid-document, it fires on the word "on" (" on", "on", "On") at about 0.9-1.6, and a bit
on "how". At the first word of a document (no earlier context to attend to) it fires on
a small set of function words, most strongly on the articles "the"/"The" and on "on".
Everything else is predicted as 0.
"""

READS = ()

ON_WORDS = {" on": 0.9, "on": 0.9, "On": 1.6, " how": 0.6}

# Activation for a word that is the first token of a document.
DOC_START = {" the": 4.8, "The": 3.7, " The": 3.2, " a": 0.8, "On": 2.6, " on": 1.7,
             "on": 1.1, " my": 1.1, " her": 0.6, " some": 0.5, " one": 0.35, " other": 0.3}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    t = prefix.position
    doc_start = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if doc_start:
        value = DOC_START.get(tok, 0.0)
    else:
        value = ON_WORDS.get(tok, 0.0)
    return carry, float(value)

