"""Detect individual Han ideograph tokens rather than merged word tokens.

Function characters and common word-building characters are weak; pronouns and
numerals are intermediate; other individual ideographs are strong.
Merged Han words usually get a small negative response, except phrases
beginning with 的. Leading-space Hangul syllables have a modest response;
merged Hangul and kana tokens have weak or negative responses.
This is a coarse lexical rule, not a character-by-character activation table.
"""
READS = ()

FUNCTION_CHARS = frozenset(
    '的了着著吗嗎呢吧啊之得地和与與及而或在于於以为為由从從把被将將'
)
COMMON_WORD_BUILDING = frozenset(
    '是有就也都所能可会會要不未无無应應让讓使'
    '上下内內外中前后後左右东西東西南北里裏間间旁'
    '年月日时時分秒周週期代次'
    '人个個们們者子生性化行成出入来到來到去用向对對等当當'
    '度法体體文利事作理力多各同每再过過更且'
)
PRONOUNS = frozenset('我你您他她它其这這那谁誰')
NUMERALS = frozenset('一二三四五六七八九十百千万萬亿億零两兩')


def is_han(c):
    return '\u3400' <= c <= '\u9fff' or '\uf900' <= c <= '\ufaff'


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token and all(is_han(c) for c in token):
        if len(token) > 1:
            if token.startswith('的'):
                value = 0.45 if len(token) == 2 else 0.30
            else:
                value = -0.12 if len(token) == 2 else -0.04
        elif token in FUNCTION_CHARS:
            value = -0.065
        elif token in COMMON_WORD_BUILDING:
            value = 0.30
        elif token in PRONOUNS or token in NUMERALS:
            value = 0.48
        else:
            value = 0.93
    elif token and all('\uac00' <= c <= '\ud7a3' for c in token):
        if len(token) == 1:
            value = 0.29 if prefix.token_strings[-1][0].isspace() else 0.05
        else:
            value = -0.10
    elif token and all('\u3040' <= c <= '\u30ff' for c in token):
        value = -0.03 if len(token) == 1 else -0.07
    else:
        value = 0.001
