"""Layer-0 MLP down_proj component 3351: a "rare Chinese character" detector.

It switches on for a token that is a single Han (Chinese) character. How strongly
depends on how common that character is:
  - the 30 most frequent Chinese characters (的 一 是 了 在 ...) give about 0,
  - the next 30 (可 也 你 对 ...) give a little,
  - the rest of the ~300 common characters give a moderate value,
  - every other single Han character (content nouns, verbs and adjectives such as
    蜂 煮 竹 衰 猛 枯) gives a strong value.
Multi-character Chinese words are slightly negative; everything else is 0.
The rule reads only the newest token and carries no state.
"""
import unicodedata

READS = ()

# Common Chinese characters, most frequent first (approximate frequency order).
COMMON = (
    "的一是不了在人有我他这个们中来上大为和国地到以说时要就出会可也你对生能而子那得于着下自之年过发后作里"
    "用道行所然家种事成方多经么去法学如都同现当没动面起看定天分还进好小部其些主样理心她本前开但因只从想实"
    "日军者意无力它与长把机十民第公此已工使情明性知全三又关点正业外将两高间由问很最重并物手应战向头文体政"
    "美相见被利什二等产或新己制身果加西斯月话合回特代内信表化老给世位次度门任常先海通教儿原东声提立及比员"
    "解水名真论处走义各入几口认条平系气题活尔更别打女变四神总何电数安少报才结反受目太量再感建务做接必场件"
    "计管期市直德资命山金指克许统区保至队形社便空决治展马科司五基眼书非则听白却界达光放强即像难且权思王象"
    "完设式选收"
)
RANK = {ch: i for i, ch in enumerate(COMMON)}


def _is_han(s):
    return len(s) == 1 and unicodedata.name(s, "").startswith("CJK UNIFIED")


def _is_cjk_word(s):
    return len(s) > 1 and all(
        unicodedata.name(c, "").startswith(("CJK UNIFIED", "HIRAGANA", "KATAKANA")) for c in s
    )


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if _is_han(s):
        rank = RANK.get(s, len(COMMON))
        if rank < 30:
            value = 0.0
        elif rank < 60:
            value = 0.25
        elif rank < len(COMMON):
            value = 0.5
        else:
            value = 0.95
    elif _is_cjk_word(s):
        value = -0.1
    else:
        value = 0.0
    return carry, float(value)

