"""Predicts +0.65 on one Han ideograph; all other tokens get zero.
This coarse script cue ignores context and differences among characters."""
READS = ()


def is_han(char):
    code = ord(char)
    return (
        0x3400 <= code <= 0x4DBF
        or 0x4E00 <= code <= 0x9FFF
        or 0xF900 <= code <= 0xFAFF
        or 0x20000 <= code <= 0x323AF
    )


