"""Approximate a layer-0 feature for time spans and the word "way".

It marks familiar calendar and clock words, especially after modifiers such as
"last", "next", or "every". It also marks "way/ways". It is a word-level
shortcut, not an interpretation of the whole sentence.
"""

READS = ()

LONG_SPANS = {
    "year", "week", "month", "season", "semester",
    "years", "weeks", "months", "seasons", "semesters",
}
SHORT_SPANS = {
    "day", "days", "night", "nights", "hour", "hours",
    "morning", "evening", "afternoon",
}
CLOCK_WORDS = {"time", "times", "moment", "moments"}
MANNER_WORDS = {"way", "ways"}
TIME_MODIFIERS = {
    "this", "that", "same", "last", "next", "past", "following",
    "previous", "each", "every",
}
SMALL_QUANTIFIERS = {"one", "few", "all"}
TIME_SPANS = LONG_SPANS | SHORT_SPANS


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower()

    if word in TIME_SPANS and previous in TIME_MODIFIERS:
        return None, -3.8
    if word in TIME_SPANS and previous in SMALL_QUANTIFIERS:
