programs.sol:
"""Approximate a negative ge/edge lexical response.

Strong triggers are edge(s), George, the short fragment ge, and selected
ji syllables. Short ge/dge suffixes, related range/region words, geographic
terms, and greater-or-equal notation have weaker responses. This is not an
"any ge substring" rule: page, image and message are not triggers.

Only the preceding token is retained, for spelling continuations, LaTeX
commands and edge(s) of. Other tokens predict zero. Smaller lexical
irregularities and longer-context variation are deliberately omitted.
"""
import re

READS = ()


def response(raw, before):
    s = raw.strip()
    word = s.strip('_.,:;()[]{}<>/\\"\'`-').lower()
    unspaced = not raw[:1].isspace()
    if '>=' in s or '≥' in s:
        return -2.1
    if word in {'edge', 'edges', 'edged'}:
        if word == 'edge' and unspaced and before.lower().endswith('w'):
            return -2.2  # wedge, including the LaTeX command
        if s[:1] in '_-.([':
            return -3.4
        if word == 'edge':
            return -5.2 if s[:1].isupper() else -4.8
        return -3.9
    if word in {'george', 'georges'}:
        return -4.3
    if word.startswith(('georg', 'geoff')):
        return -1.8
    if word == 'ge':
        if before.endswith('\\'):
            return -2.1  # LaTeX greater-or-equal command
        return -3.4 if s[:1].isupper() else -3.9
    if unspaced and before.lower().endswith('g') and word in {'ger', 'ged', 'ging'}:
        return -0.6  # doubled g, as in tagged and logging
    # Short ge prefixes and suffix spellings.
    if word in {'ger', 'geb', 'gef', 'ges'}:
        return -2.9 if word == 'ges' and unspaced and s.islower() else -1.9
    if word in {'gel', 'geh', 'ged', 'gep', 'gek', 'gez', 'gew', 'gest', 'gesch'}:
        return -1.3
    if word in {'nge', 'enge'}:
        return -3.6
    if re.fullmatch(r'[aeiou]?(?:n|r)ge|[iou]dge', word):
        if before.lower().endswith('arr') or word in {'urge', 'unge'}:
            return -1.0 if word != 'unge' else -1.6
        return -2.5
    if word == 'oge':
        return -2.7
    if re.fullmatch(r'[aeiou]ge(?:r|s|d|n|m)?', word):
        return -0.5 if word in {'igen', 'ogen'} else -1.0
    # Geographic stems and longer ge-containing fragments.
    if word.startswith(('geograph', 'geolog')) or word == 'geo':
        return -1.5
    if word.startswith('geometr'):
        return -0.6
    if re.fullmatch(r'[aei]ng(?:es|er|en)|ver(?:age|gence)', word):
        return -1.4
    if re.fullmatch(r'(?:(?:con|di)?verg|emerg)(?:e|es|ed|ing|ence|ent)', word):
        return -1.4
    if word in {'hedge', 'wedge', 'ridge', 'ledge', 'forge'}:
        return -2.2
    if word in {'gen', 'gem', 'age', 'ages', 'ging', 'inger', 'igen'}:
        return -0.9
    if word in {'range', 'ranges', 'arange', 'bridge', 'bridges', 'region', 'regions'}:
        return -0.8
    if word in {'merge', 'merges', 'hinge', 'hinges', 'gauge'}:
        return -1.3
    if word in {'average', 'advantage', 'advantages', 'leverage', 'git', 'gi', 'gy'}:
        return -0.6 if not s.startswith('.') else -0.1
    # Selected non-Latin syllables and boundary/geography vocabulary.
    if word == '지':
        return -3.3 if unspaced else -2.3
    if word == 'ジ':
        return -2.2
    if word in {'じ', 'ジェ', 'ゲ', 'げ', 'ギ', 'ги', 'ج', 'จ', 'ʒ'}:
        return -0.6
    if word in {'ге', 'дж', '게', '거'}:
        return -0.8
    if word in {'边', '邊', '边缘', '边界', '地理', '地域', '地区', '橋', '桥'}:
        return -1.0
    if word == 'of' and before.strip().lower() in {'edge', 'edges'}:
        return -1.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    raw = prefix.token_strings[-1]
    return (doc, raw), response(raw, before)

programs.haiku:
"""Component layers.0.mlp.down_proj:3355 (Qwen3-1.7B, layer 0 MLP down projection).

What it does, in plain terms: it is a "ge" detector. It goes strongly negative on
the token that is the spelling "ge" (or the word "edge", "George", the Cyrillic "ге",
or the comparison symbol "≥" / ">="), and goes moderately negative on other tokens
that contain "ge" or "dge" (bridge, judge, merge, range, anger, age, ...). The
strength falls with word length: short "ge" fragments (German/Dutch/English
syllables like "ge", "ger", "ged") fire more than long words that merely contain
"ge". Everything else is about zero.

The program reads only the newest token, so it has no carry state. Activations
are predicted from the token's spelling alone.
"""

READS = ()

# Strongest: the bare "ge" spelling, the words "edge"/"George", Cyrillic "ге",
# and the "greater or equal" symbol (written ">=" or "≥").
STRONG = {"ge", "george", "edge", "edges", "ге"}
GE_SYMBOLS = {">=", "≥"}


def value(token: str) -> float:
    w = token.strip().lower()
    if w in STRONG:
        return -3.8
    if w in GE_SYMBOLS:
        return -2.0
    if "dge" in w or "edge" in w:
        return -2.0
    if "ge" in w:
        if len(w) <= 3:
            return -0.8
        if len(w) <= 5:
            return -0.4
        return -0.1
    return 0.0


def step(carry, prefix, upstream):
    # Token-local: the activation depends only on the newest token's text.
    return None, value(prefix.token_strings[-1])

