programs.sol:
"""Recognize letters attached to numbers, and labels starting chat messages.

An unspaced Latin suffix after a numeric token gives a positive response.
Hexadecimal letters respond especially strongly; ordinal endings weakly.
Chat speaker labels give a negative response, smaller at a document's start.
Other tokens are predicted near zero. State resets between documents.
"""
READS = ()
HEX_LOWER = frozenset('abcdef')
HEX_UPPER = frozenset('ABCDEF')
ORDINAL_ENDINGS = frozenset(('st', 'nd', 'rd', 'th'))
METRIC_UNITS = frozenset(('mm', 'cm', 'km', 'mg', 'kg', 'ml', 'mL', 'ms'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    value = 0.0
    if previous == '<|im_start|>':
        if token == 'assistant':
            value = -0.64 if position == 1 else -1.13
        elif token == 'user':
            value = -0.52 if position == 1 else -1.01
    elif previous.isdecimal() and token.isascii() and token.isalpha():
        letters = set(token)
        if token in ORDINAL_ENDINGS:
            value = 0.36 if token == 'st' else 0.12
        elif letters <= HEX_LOWER:
            value = 1.07 if len(token) == 1 else 1.35
        elif letters <= HEX_UPPER:
            value = 0.82
        elif (len(token) > 1 and token.startswith('x')
              and set(token[1:].lower()) <= HEX_LOWER):
            value = 0.85
        elif token in METRIC_UNITS:
            value = 0.74
        elif token == 's':
            value = 0.43
        elif len(token) == 1:
            value = 0.67
        else:
            value = min(0.61, 1.30 / len(token))
    return (doc, token, position + 1), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:3356 -- a "letter right after a digit" detector, plus a chat-role detector.

What it does, in plain terms:
- Fires positively on a letter that sits directly after a digit, as in "2x", "3b", "8a",
  "0xc0002ec5a" (hex). Qwen splits digits into single tokens, so the letter is the token
  right after a digit token. Single letters are strongest; the strength grows with how
  long the unbroken letters-and-digits string is (hex addresses, IDs and codes are high,
  "2x" in prose is moderate). Ordinal endings ("5th", "2nd", "3rd", "1st") and plural
  "1990s" are near zero or weak.
- Fires negatively on the role names that open a chat turn: "assistant" and "user" right
  after "<|im_start|>".
- Predicts 0 everywhere else. Most positions are small and diffuse, which this does not model.
"""

READS = ()

ROLE_NEG = {"assistant": -1.13, "user": -0.87}
ORDINAL_ENDINGS = {"th", "nd", "rd", "st"}


def is_alnum(s):
    return len(s) > 0 and all(c.isascii() and c.isalnum() for c in s)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    prev = prefix.token_strings[-2]
    if prev == "<|im_start|>" and tok in ROLE_NEG:
        return None, ROLE_NEG[tok]
    if len(prev) == 1 and prev.isdigit() and tok.isascii() and tok.isalpha():
        if tok in ORDINAL_ENDINGS:
            return None, 0.05
        if tok == "s":
            return None, 0.45
        # how many letter/digit tokens in a row end at the digit (the length of the "word")
        run = 0
        for i in range(len(prefix.token_strings) - 2, -1, -1):
            if prefix.document_ids[i] != prefix.document_ids[-1] or not is_alnum(prefix.token_strings[i]):
                break
            run += 1
        strength = min(0.5 + 0.1 * run, 1.4)
        return None, strength if len(tok) == 1 else 0.6 * strength
    return None, 0.0


if __name__ == "__main__":
    # A made-up token list (Qwen splits digits into single tokens): print the nonzero predictions.
    from types import SimpleNamespace

    tokens = ["<|im_start|>", "assistant", "\n", "x", "=", "2", "x", ",", "1", "9", "9", "0", "s", "5", "th", "0", "x", "c", "0", "0", "0", "2", "e", "c"]
    carry, shown = None, []
    for t in range(len(tokens)):
        prefix = SimpleNamespace(token_strings=tokens[: t + 1], token_ids=list(range(t + 1)), document_ids=[0] * (t + 1))
        carry, value = step(carry, prefix, {})
        if value:
            shown.append((tokens[t], round(value, 2)))
    print(shown)

programs.luna:
"""Mark short numeric labels and units, plus negative chat-role boundary tokens.

Letters and short suffixes right after digits cover compact codes, hexadecimal
text, and variable/figure labels. A named set covers common attached units.
The role rule captures user/assistant labels following a message-start marker.
"""

READS = ()

# Familiar abbreviations that commonly touch a number: units, scales, and
# clock suffixes. They are spelling conventions, not model token IDs.
NUMBER_UNITS = {
    "px", "pt", "mm", "cm", "km", "in", "ft", "yd", "mi",
    "ms", "GHz", "MHz", "kHz", "KB", "kb", "MB", "GB",
    "kg", "mg", "dB", "db", "deg", "AM", "PM", "am", "pm",
}


def step(carry, prefix, upstream):
    position = prefix.position
    document = prefix.document_ids[position]

    if carry is None or carry[0] != document:
        document_position = 0
    else:
        document_position = carry[1] + 1
    new_carry = (document, document_position)

    token = prefix.token_strings[position]
    previous = ""
    if position > 0 and prefix.document_ids[position - 1] == document:
        previous = prefix.token_strings[position - 1]

    if token in ("assistant", "user") and previous == "<|im_start|>":
        if token == "user" and document_position < 5:
            return new_carry, -0.52
        return new_carry, -1.12

    follows_digit = bool(previous and previous[-1].isdigit())
    if follows_digit and token.isascii() and token.isalpha():
        if len(token) == 1:
            if token.isupper():
                return new_carry, 0.75
            if token in "abcdef":
                return new_carry, 1.15
            if token == "s":
                return new_carry, 0.50
            return new_carry, 0.74

        if token in NUMBER_UNITS:
            return new_carry, 0.62

        if 1 < len(token) <= 4:
            if all(character in "abcdefABCDEF" for character in token):
                return new_carry, 1.10 if token.islower() else 0.80
            return new_carry, 0.45

    return new_carry, 0.0

programs.sol:
"""A local quote-boundary response, using the current and previous token.

Likely closing quotes/backticks are positive. Space-led tokens just after a
quote are also positive, especially linking words and string-combining
operators. Unspaced words just inside quotes are weakly negative. Attached
punctuation or newlines attenuate the next-token response. This uses local
token shape, not a full parse of quotation nesting.
"""
READS = ()
QUOTES = "\"'`“”‘’«»「」『』《》„′″‹›"
LEFT_QUOTES = "“‘«「『《„‹"
RIGHT_QUOTES = "”’»」』》′″›"
LINK_WORDS = frozenset("""
and or but if of in to as for by with from on at is was are were be been
have has had do does did can could will would should may might must not
when that which who whose
""".split())
OPERATORS = frozenset('- * / = => -> & && | || : \\'.split())


def quote_parts(s):
    for i in range(len(s) - 1, -1, -1):
        if s[i] in QUOTES:
            return s[i], s[:i], s[i + 1:]
    return None


def closing_response(s, previous, parts):
    q, before, after = parts
    if any(c.isalnum() for c in after):
        return 1.1 if q in RIGHT_QUOTES and q != '’' else 0.0
    if q in LEFT_QUOTES or s.count(q) >= 3:
        return 0.0
    if before and (before.isspace() or before.endswith(tuple('([{=:+'))):
        return 0.55 if after.strip() in {',', ';', ':'} or '\n' in after else -0.02
    if q == '`':
        return 0.25 if s.count(q) == 1 else 0.0
    if not before and not after:
        opening = not previous or previous[-1].isspace() or previous[-1] in '([{='
        elision = q in "'’" and previous.strip().lower() in {'l', 'd', 'qu', 'dell'}
        prime = q in "'’" and previous.startswith(' ') and len(previous.strip()) == 1
        return 0.0 if opening or elision or prime else 0.65 if q in "'’" else 0.85
    return 0.28 if before.endswith('\\') and not after else 0.55


def following_response(s, parts):
    q, before, after = parts
    tick, single = q == '`', q in "'‘’"
    word, spaced = s.strip().lower(), s.startswith(' ')
    if any(c.isalnum() for c in after):
        return 0.0
    if '\n' in after:
        return 0.2 if not word and not after.strip() else 0.0
    if after.strip():
        return 0.25 if spaced and any(c.isalpha() for c in s) else 0.0
    if not word:
        return 0.5 if tick else 1.0
    if spaced:
        if word in {'+', '%', '<<', '.'}:
            strong = before and before.endswith(tuple(' ([{=:+'))
            value = 5.3 if strong else 3.1
            if word == '%':
                value = 4.3
            elif word == '.':
                value = 3.4
            elif word == '<<':
                value = min(value, 4.5)
            return 2.4 if '\n' in s else value
        if word in OPERATORS or word.startswith('('):
            return 1.0 if tick else 1.8
        if word in LINK_WORDS:
            return 0.7 if tick else 1.4 if single else 1.5
        return 0.7 if tick else 0.6 if single else 0.95
    if any(c.isalpha() for c in s):
        return -0.13 if tick else -0.18 if single else -0.08
    if word.isdigit():
        return 0.0
    return 1.5 if word == '+' else 0.5


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    current, previous = quote_parts(s), quote_parts(prev)
    if current:
        value = closing_response(s, prev, current)
    else:
        value = following_response(s, previous) if previous else 0.0
    return (doc, s), float(value)

programs.haiku:
"""A closing quotation mark, and the word or operator that comes right after one.

When a quoted string or quoted phrase ends (a double quote such as the one in  "text" , or a
curly quote, or a backtick), the model's MLP fires on the quote itself, and more strongly on the
next token. The next token is strongest when it is a code operator such as + or << (as in
  "Name: " + name ), and moderate for a plain word after the quote. Single quotes and
apostrophes fire much less. Opening quotes (after a space or a bracket, as in ` "` or `("`)
do not fire.

Stateless: reads only the current token and the one before it.
"""
READS = ()

DOUBLE_QUOTES = set('"“”「」『』《》«»')
SINGLE_QUOTES = set("'‘’`")
OPENING_MARKS = set("“「『《«‘")
AFTER_WHICH_IT_OPENS = set(" \t([{=<")
OPERATORS = {" +", " +\n", " <<", " %", " =>", " ->", " |", " ||", " -", " or"}


def closes(tok, marks):
    """True if the first quotation mark of `marks` in the token closes a quote."""
    for i, c in enumerate(tok):
        if c in marks:
            before = tok[:i]
            return c not in OPENING_MARKS and (before == "" or before[-1] not in AFTER_WHICH_IT_OPENS)
    return False


def has_mark(tok, marks):
    return any(c in marks for c in tok)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    both = DOUBLE_QUOTES | SINGLE_QUOTES
    if has_mark(tok, both):
        if closes(tok, both):
            return None, 0.55 if has_mark(tok, DOUBLE_QUOTES) else 0.15
        return None, 0.0
    if has_mark(prev, both) and tok in OPERATORS:
        return None, 3.0
    word = tok[:1] == " " and tok.strip().isalpha()
    if closes(prev, DOUBLE_QUOTES):
        return None, 0.8 if word else 0.2
    if closes(prev, SINGLE_QUOTES) and word:
        return None, 0.1
    return None, 0.0

programs.luna:
"""Predict small pulses around quoted, backticked, or marked-off text.

A closing mark predicts a pulse there; the first word or operator after
an opening or closing mark gets one too. The quoted content is not read.
"""

READS = ()


OPERATORS = "=+-*/%<>!&|^~:."


def is_word(text):
    return any(ch.isalnum() for ch in text)


def is_operator(text):
    chars = text.strip()
    return bool(chars) and all(ch in OPERATORS for ch in chars)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        double_open = single_open = backtick_open = False
        pending = False
        previous_char = " "
    else:
        _, double_open, single_open, backtick_open, pending, previous_char = carry

    text = prefix.token_strings[-1]
    closed = opened = False
    last_char = previous_char

    for i, ch in enumerate(text):
        before = text[i - 1] if i else last_char
        after = text[i + 1] if i + 1 < len(text) else " "
        if ch == '"':
            double_open = not double_open
            if double_open:
                opened = True
            else:
                closed = True
        elif ch == "'":
            if before.isalnum() and after.isalnum():
                pass  # apostrophe inside a word
            elif single_open or before.isalnum():
                single_open = False
                closed = True
            else:
                single_open = True
                opened = True
        elif ch in "“«「『‘":
            opened = True
        elif ch in "”»」』":
            closed = True
        elif ch == "’":
            if not after.isalnum():
                closed = True
        elif ch == "`":
            backtick_open = not backtick_open
            if backtick_open:
                opened = True
            else:
                closed = True
        last_char = ch

    word = is_word(text)
    operator = is_operator(text)
    value = 0.65 if closed else 0.0
    if pending and (word or operator):
        value += 0.75
    if not pending and opened and word:
        value += 0.15

    consumed = word or operator
    pending = closed or (opened and not word) or (pending and not consumed)
    carry = (doc, double_open, single_open, backtick_open, pending, last_char)
    return carry, 0.3 * value

programs.sol:
"""Detect unfinished opening delimiters, especially in symbolic expressions.

'(' is strongly negative when joined to an operator. With a leading space,
it is weak after ordinary words but stronger after function words,
code-control words or punctuation. Quotes and operands in the same token
weaken that signal. Square brackets and mathematical scripts are weaker
relatives. Ordinary text is predicted zero. Only the previous token is kept.
"""
READS = ()
CONTROL = {'if', 'for', 'catch', 'elif', 'foreach', 'func', 'function'}
CONNECTORS = {'and', 'or', 'is', 'was', 'were', 'be', 'been', 'being', 'to'}
FUNCTION_WORDS = {
    'of', 'by', 'as', 'with', 'from', 'through', 'over', 'between', 'under',
    'without', 'within', 'about', 'upon', 'the', 'that', 'are', 'so',
}
# Strength of the symbol immediately before an unfinished parenthesis.
SYMBOL = {
    '!': -5.55, '-': -5.3, '+': -5.2, '=': -4.55, '_': -4.4,
    '.': -4.5, '^': -4.1, '>': -4.6, '<': -5.5, '$': -4.15,
    '*': -3.9, '/': -3.8, ',': -3.85, ':': -5.2, '?': -4.3,
    ')': -3.0, ']': -3.75, '}': -2.0, '{': -2.6, '[': -2.85,
    '`': -4.05, '"': -4.15, "'": -4.7, '|': -4.4, '&': -5.4,
}


def context(previous):
    p = previous.strip()
    if not p:
        return -1.0
    spaced, word = previous[0].isspace(), p.lower()
    if word in {'while', 'return', 'yield'}:
        return -1.95
    if word in CONTROL:
        return -1.4
    if spaced and word in CONNECTORS:
        return -1.3
    if spaced and word in FUNCTION_WORDS:
        return -0.95
    if spaced and word in {'at', 'in', 'on', 'it', 'this', 'a', 'an'}:
        return -0.55
    if not any(c.isalnum() for c in p):
        if p[-1] in '=+-/^&|':
            return -2.1 if spaced or len(p) > 1 else -1.75
        return -1.5 if p[-1] in ':,;)([]<>' else -0.75
    if p.isdigit():
        return -0.34
    if not p.isascii():
        return -0.08
    if p.startswith(('.', '_')) or '.' in p:
        return -0.7
    if len(p) == 1:
        return -0.6 if spaced else -0.23
    if p.isupper():
        return -0.3
    if not spaced and not p.islower():
        return -0.55
    return -0.1 if spaced and p.islower() else 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s, spaced = token.strip(), token.startswith(' ')
    value = 0.0
    if '(' in s and not any(c.isalnum() for c in s):
        before, after = s.rsplit('(', 1)
        if ')' not in after:
            if before:
                if set(before) == {'('}:
                    value = -3.0
                elif before.endswith('\\'):
                    value = -0.7
                elif before == '__':  # Python double-underscore methods.
                    value = -3.95 if previous.strip() == 'init' else -6.2
                else:
                    value = SYMBOL.get(before[-1], -4.5)
                    if before.startswith('(') and before.endswith('!'):
                        value += 1.3
                    if spaced and before[-1] in '*/!&<>' and before[0] != '(':
                        value -= 0.9
                if not after and '\n' in token:
                    value *= 0.6
                elif after and after != '\\':
                    value *= 0.45
            elif after == '-':
                value = -0.48
            elif after == '\\':
                value = -0.18 if spaced else -0.35
            elif after.startswith('['):
                value = 0.12 if spaced else -0.45
            elif not after:
                p = previous.strip()
                value = context(previous) if spaced else -1.5
                if not spaced and (not p or '\n' in previous or p in {'sqrt', 'left'}):
                    value = -0.9
                elif not spaced and p.isdigit():
                    value = -1.15
                elif not spaced and len(p) == 1:
                    value = -1.33
                if '\n' in token:
                    value = -0.85
    elif s.endswith('[') and not any(c.isalnum() for c in s):
        p = previous.strip()
        if s == '[':
            value = (-0.55 if p and p[-1] in ':=+' else -0.05) if spaced else -0.55
        else:
            value = -2.55 if '#' in s else (-0.95 if s == '][' else -1.5)
        if s == '[[' or s.endswith('\\['):
            value = -0.4
    elif s.endswith(('_{', '^{')):
        value = -0.8
    elif s == '{"' and not spaced:
        value = 0.32
    elif s.endswith('（'):
        value = -3.2 if s != '（' else (-1.55 if spaced else -0.25)
    return (doc, token), float(value)

programs.haiku:
"""Opening-bracket detector (layer-0 MLP component 3359).

It fires negatively on tokens that open a bracket inside code or maths:
glued operator-brackets such as "*(", "!(", "](" are strongly negative, and a
spaced " (" or bare "(" is negative when it opens an expression (after "=",
an operator or a keyword) but near zero when it opens a prose aside after a
word. Everything else is 0.
"""
READS = ()

KEYWORDS = {"if", "for", "while", "return", "and", "or", "not", "is", "in",
            "else", "elif", "with", "when", "then", "assert"}
OPERATOR_CHARS = set("=+-*/<>&|!%^~?:,;")


def _prev_class(prev):
    s = prev.strip()
    if s == "":
        return "blank"
    if s.isdigit():
        return "digit"
    if s in KEYWORDS:
        return "keyword"
    if all(c in OPERATOR_CHARS for c in s):
        return "operator"
    if s.isascii() and all(c.isalnum() or c == "_" for c in s):
        return "word"
    return "other"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if tok in (" (", "("):
        cls = _prev_class(prev)
        if tok == "(":
            return carry, -1.3
        if cls in ("keyword", "operator"):
            return carry, -1.8
        if cls == "other" or cls == "blank":
            return carry, -0.8
        if cls == "digit":
            return carry, -0.3
        return carry, -0.2  # after a word: mostly prose asides
    if tok.endswith("(") and len(tok) > 1:
        return carry, -4.0  # glued operator + bracket, e.g. "*(", "!(", "]("
    if tok in ("[", " ["):
        return carry, -0.5
    return carry, 0.0

programs.luna:
"""Approximate a sparse response to opening punctuation in token text.

The clearest signal is a standalone opening parenthesis, with much larger
negative responses when punctuation is attached before it. A bare square
bracket has a smaller response, and other token shapes are usually quiet.
"""

READS: tuple[str, ...] = ()
OPENERS = "([{"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    openings = "".join(ch for ch in text if ch in OPENERS)
    if not openings:
        return None, 0.0

    positions = [i for i, ch in enumerate(text) if ch in OPENERS]
    first, last = positions[0], positions[-1]
    before = text[:first]
    after = text[last + 1:]
    attached_punctuation = bool(before) and all(
        not ch.isalnum() and not ch.isspace() for ch in before
    )

    if before and not attached_punctuation:
        return None, 0.0

    if attached_punctuation and after:
        return None, -1.1 if "(" in openings else 0.0
    if attached_punctuation:
        if "(" in openings:
            return None, -4.2
        if "[" in openings:
            return None, -1.55
        return None, -0.4

    if after:
        return None, 0.0
    if openings == "(":
        return None, -0.4 if token.startswith(" ") else -1.25
    if openings == "((":
        return None, -3.8
    if openings == "[":
        return None, 0.0 if token.startswith(" ") else -0.47
    return None, 0.0

programs.sol:
"""A lexical detector for uniformity and uniforms (the clothing).

Uniform is the strongest trigger. The shape suffix -iform also fires,
including when it completes 'un' to spell uniform or non-uniform. Endings
retain a smaller response. Chinese words for uniform clothing and evenness
and OpenGL shader-uniform APIs are included. Case and token prefixes can
change response strength, but not the recognized word family.
Unmodeled tokens receive zero, not a prediction of semantic uniformity.
"""
READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower().lstrip('._')
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2].strip().lower()

    if word == 'uniform':
        value = 5.0 if raw.startswith('.') else (
            4.1 if raw == 'Uniform' or raw.startswith('_') else 4.45)
    elif word == 'uniforms':
        value = 3.2
    elif word == 'uniformly':
        value = 3.05
    elif word == 'iform':
        if raw.isupper():
            value = 5.2
        elif previous.endswith('-un'):
            value = 5.6
        elif previous.endswith('un'):
            value = 4.6
        else:
            value = 3.2
    elif word in ('e', 'ity', 'ité') and previous.endswith('uniform'):
        value = {'e': 1.75, 'ity': 1.73, 'ité': 1.15}[word]
    elif word in ('e', 'es', 'is', 'ity', 'ula') and previous == 'iform':
        value = 1.18 if word == 'ity' else (
            0.3 if word == 'ula' else 0.7)
    elif word == 'distribution' and previous.endswith('uniform'):
        value = 0.8
    elif word in ('gluniform', 'glgetuniformlocation'):
        value = 3.2  # OpenGL shader-uniform APIs.
    elif raw in ('制服', '均匀'):  # Uniform / livery; even / uniform.
        value = 2.7
    elif raw == '匀':  # Even, uniform.
        value = 2.0
    elif raw == '服' or raw.endswith('私服'):
        value = 1.2  # Clothing morpheme; also private-server names.
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Layer-0 MLP feature for the word "uniform".

What it does: this component writes a large value into the residual stream on the
token that spells "uniform" in English: " uniform", "Uniform", "uniforms" and
"uniformly" (the adverb is weaker), and on the tail "iform" when the tokenizer splits
the word as "Un" + "iform" (or "...iform" inside words like "pluteliformis").
It is weaker on the Chinese words for uniform or even: 制服 (uniform clothing),
均匀 and 匀 (even, evenly distributed). Everywhere else it is near zero, and it does
not respond to related words such as "unified", "unique", "equal" or "evenly".

It is a spelling detector, so it looks only at the newest token. Each value is the
average activation for that kind of match in the training data.
"""

READS = ()

UNIFORM_CHINESE = {"制服", "均匀", "匀"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if "uniform" in word:
        if word.endswith("ly"):
            value = 2.9  # "uniformly"
        elif word.endswith("s"):
            value = 3.3  # "uniforms"
        else:
            value = 4.3  # " uniform", "Uniform"
    elif word == "iform":
        value = 3.4  # second half of a split "uniform"
    elif token in UNIFORM_CHINESE:
        value = 2.5
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""A token-level child and kinship cue, not a full semantic classifier.

The literal singular 'child' is much stronger than plurals or relatives.
The cue also covers tree nodes in code, several translations of 'child',
the 'ild' spelling fragment, and 'kind' and Christ-related spellings.
Short phrase rules cover possessives, 'child of', and weaker uses after
determiners or modifiers.
Everything else is zero; most fine-grained token/context variation is omitted.
"""
READS = ()

CHILD_TRANSLATIONS = {'niño', 'niños', 'enfant', 'enfants', 'anak',
                      'дети', 'детей', 'ребенка', 'ребёнка', 'dzieci'}
# Related vocabulary grouped by approximate response strength.
STRONG_RELATED = {
    'kid', 'kids', 'babies', 'infants', 'boy', 'daughter', 'offspring',
    'juvenile', 'pediatric', 'parental', 'parenting',
}
WEAK_RELATED = {
    'girl', 'girls', 'boys', 'youth', 'teen', 'son', 'sons', 'siblings',
    'daughters', 'grandson', 'granddaughter', 'descendants', 'families',
    'familie', 'famille', 'familia', 'fetal', 'fetus', 'orphans', 'род',
    '家长', '家族', '女孩', '男孩', '小女孩', '宝宝',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lower()
    bare = word.lstrip('._-([')
    value = 0.0
    if bare == 'child':
        value = 6.3
        if token == ' child':
            value = 6.1
            if prev in {'a', 'your', 'each', 'every', 'young', 'little'}:
                value = 5.4
            elif prev in {'first', 'last', 'left', 'right', 'next'}:
                value = 4.7
        elif text.startswith(('_', '(', '[')):
            value = 4.8
    elif word == 'childs':
        value = 3.7
    elif bare == 'children' or word in {'childhood', 'childcare'}:
        value = 2.1
    elif 'children' in word or word in {'childish', 'childbirth'}:
        value = 1.3
    elif word.endswith('child'):
        value = 1.0
    elif '孩子' in text:
        value = 1.3 if '们' in text else 2.25
    elif text in {'儿童', '兒童', '亲子', '孩', '小孩'}:
        value = 2.1
    elif text in {'子', '儿', '兒', '童', '儿子', '胎', '娃娃', '子ども'}:
        value = 1.0
    elif word in {'ребен', 'ребён', 'ребенок', 'ребёнок', 'çocuk'}:
        value = 2.2
    elif word in CHILD_TRANSLATIONS or word in {'baby', 'infant', 'sibling'}:
        value = 1.05
    elif word in STRONG_RELATED:
        value = 0.8
    elif word in WEAK_RELATED:
        value = 0.5
    elif word == 'family':
        value = 1.25 if text[:1].isupper() else 1.0
    elif bare == 'parent':
        value = 0.75
    elif word in {'parents', 'mother', 'father', 'birth', 'young', 'brother'}:
        value = 0.25
    elif bare in {'kind', 'kinder'}:
        value = 0.8 if prev == 'a' else 1.3
    elif word.startswith('christ'):
        value = 1.1 if word == 'christ' else 0.8
        if word == 'christmas':
            value = 0.5
    elif word == 'ild':
        value = 0.8
    if word == 'of':
        value = {'child': 1.15, 'family': 0.33, 'children': 0.19,
                 'kind': 0.21}.get(prev, 0.0)
    elif word in {"'s", '’s'}:
        value = {'child': 0.4, 'children': 0.23, 'baby': 0.15,
                 'family': 0.15}.get(prev, 0.0)
    return (doc, word), float(value)

"""A partial lexical model of document boundaries and formal public address.

It fires on end-of-text, 'whether', public offices/institutions, and
welcoming or addressing people. Elections and legal rules go negative.
Case, personal-title abbreviations, compound offices and possessives
refine these responses. Chinese offices use their familiar title endings.
Other lexical responses of the component are deliberately left out.
"""
READS = ()

# Each line groups words by a recognizable meaning, not by token id.
GROUPS = (
    ('president senator', 0.77),
    ('chairman secretary', 0.57),
    ('minister ambassador commissioner governor archbishop chancellor', 0.32),
    ('mrs ms lord lady sir hon', 0.34),
    ('congress parliament court commission government governments committee', 0.34),
    ('administration republic union assembly', 0.24),
    ('nation', 0.60),
    ('nations senate', 0.46),
    ('country countries world', 0.16),
    ('today tonight', 0.38),
    ('join joined joining welcome welcoming', 0.46),
    ('dear friend friends colleague colleagues peers thank pleasure', 0.31),
    ('distinguished respected comrades', 0.43),
    ('honor honour honored honoured proud brother sister', 0.22),
    ('member members chief director deputy representative representatives', 0.13),
    ('authorities staff counsel vice', 0.21),
    ('election elections statute statutes', -0.36),
    ('regulation regulations provision provisions doctrine judicial', -0.29),
    ('law laws legislation', -0.17),
    ('local county international american', -0.15),
)
LEXICON = {w: v for words, v in GROUPS for w in words.split()}
CAPITAL_BOOST = set('chairman secretary minister ambassador governor'.split())
ABBREVIATIONS = dict(mr=0.47, mrs=0.22, ms=0.24, dr=0.15,
                     sen=0.12, rep=0.08, gov=0.11, st=0.03)
MARKERS = {'<|im_end|>': -0.02, '<think>': -0.10, '</think>': -0.03,
           '<tool_response>': -0.05, '</tool_response>': -0.19}
# Chinese head-of-office endings; prefixes can identify the deputy or locality.
HIGH_OFFICES = ('主席', '总统', '總統', '董事长', '董事長',
                '总经理', '總經理')
OTHER_OFFICES = ('书记', '書記', '总理', '總理', '首相', '市长', '市長',
                 '部长', '部長', '局长', '局長', '主任')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    prev, last = ('', '') if first else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    low = word.lower()
    cap = word[:1].isupper()
    spaced = token.startswith(' ')
    value = LEXICON.get(low, -0.002)

    if low in CAPITAL_BOOST and cap:
        value += 0.19
    if cap and low in {'president', 'senator'}:
        value += 0.11
    if cap and low in {'congress', 'parliament', 'court', 'commission', 'government'}:
        value += 0.10
    if word == 'Mr':
        value = 0.57 if spaced else 0.45
    if word in {'State', 'States', 'House', 'Treasury', 'General'}:
        value = {'State': 0.20, 'States': 0.41, 'House': 0.46,
                 'Treasury': 0.44, 'General': 0.30}[word]
        if not spaced:
            value *= 0.5
    if low == 'ms' and word != 'Ms':
        value = 0.03  # usually milliseconds rather than an honorific
    if not spaced and low in {'join', 'joined', 'welcome', 'thank', 'dear'}:
        value *= 0.6
    if low in {'country', 'countries', 'local'} and not spaced:
        value = 0.0
    if low == 'whether':
        value = 0.69 + 0.07 * cap
    if low == 'while':
        value = 0.16 + 0.09 * cap
    if word in {'And', 'But', 'So'}:
        value = (0.20 if word == 'And' else 0.13) * (1.0 if spaced else 0.68)
    if word == 'but':
        value = -0.04

    if word.endswith(HIGH_OFFICES):
        value = 0.80
    elif word.endswith(OTHER_OFFICES):
        value = 0.56
    elif word in {'政府', '人民', '副', '厅', '廳', '委',
                  '各位', '欢迎', '歡迎'}:
        value = 0.40
    elif word in {'国家', '國家', '国', '國', '代表',
                  '朋友', '是否', '长', '長'}:
        value = 0.28
    elif word in {'法律', '法规', '法規', '规定', '規定',
                  '规范', '規範', '标准', '標準'}:
        value = -0.30

    # A title also colors the punctuation or linking word that completes it.
    if token == '.' and prev in ABBREVIATIONS:
        value = ABBREVIATIONS[prev]
    if low == 'of' and prev in {'president', 'secretary', 'chairman', 'minister'}:
        value = 0.39
    if low in {'country', 'countries', 'nation', 'nations', 'friend', 'friends'}:
        if prev in {'my', 'our', 'dear'}:
            value += 0.42
        elif prev in {'this', 'whole', 'your'}:
            value += 0.17
    if word == 'General' and prev in {'attorney', 'solicitor', 'secretary'}:
        value = 1.05
    if word == 'Minister' and prev == 'prime':
        value = 0.73
    if word in {'President', 'Chairman', 'Secretary'} and prev == 'mr':
        value = 1.40
    if word == 'President' and prev == 'vice':
        value = 1.10

    if first and low == 'the':
        value = -0.13 if cap else -0.06
    if first and token == ' ':
        value = 0.10
    if token in MARKERS:
        value = MARKERS[token]
    if token == '<|im_start|>':
        value = 0.18 if first else 0.02
    if token == '<|endoftext|>':
        value = 0.60 if first else (0.84 if last == '<|im_end|>' else 0.90)

    if not token.isspace():
        last = token
    # Join consecutive alphabetic pieces so 'Attorney' works when split.
    if low.isalpha() and not spaced and prev.isalpha():
        prev = (prev + low)[-32:]
    else:
        prev = low
    return (doc, prev, last), float(value)

programs.haiku:
"""Layer-0 MLP component 3363 (down_proj), a "political office / government title" detector.

What it does: it writes a positive push into the residual stream on
  1. the end-of-text token that separates documents (strongest, about 0.9);
  2. words that name a political or public office or a formal title, and that usually
     come right before a name or an office ("Mr", "President", "Secretary", "Minister",
     "Senator", "Chairman", "Lady", "gentlemen") (about 0.7);
  3. broader political / civic nouns ("States", "nation", "government", "Congress",
     "Court", "House", "country", "election"-like context) (about 0.4); "election" is negative (about -0.5);
  4. "of" or "for" right after one of those words ("President of", "Minister for") (0.3).
Everything else predicts 0. The values are the typical activations on training text.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"

TITLES = {
    " Mr", " Mrs", " Ms", " Mr.", " Lady", " Lord", " gentlemen", " President", " president",
    " presidente", " Vice", " Secretary", " Secretary-General", " Chairman", " Minister",
    " minister", " Senator", " Governor", " Congressman", " Ambassador", " Chancellor",
    " Premier", " Prime", " Speaker", " Commissioner", " Director", " Deputy", " Judge",
}

CIVIC = {
    " States", " State", " nation", " country", " government", " Government", " Congress",
    " Court", " court", " House", " Union", " Parliament", " Senate", " today", " whether",
    " Whether", " Party", " party",
}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    if tok == " election":
        value = -0.5
    elif tok == END_OF_TEXT:
        value = 0.9
    elif tok in TITLES:
        value = 0.7
    elif tok in CIVIC:
        value = 0.4
    elif tok in (" of", " for") and (prev in TITLES or prev in CIVIC):
        value = 0.3
    else:
        value = 0.0
    return None, value

programs.luna:
"""Predict the strong end-of-text pulse and smaller signals on official,
political, and legal words; unrelated tokens get a quiet zero prediction."""
READS = ()

END = "<|endoftext|>"
OFFICIAL_OR_LEGAL = {
    "board", "country", "congress", "minister", "archbishop",
    "lord", "court", "nation", "mr", "plaint",
    "副总经理", "市长",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == END:
        return None, 0.9
    word = token.strip().casefold()
    if word == "whether":
        return None, 0.6
    if word in OFFICIAL_OR_LEGAL:
        return None, 0.4
    return None, 0.0

programs.sol:
"""Detect coordination, plus a rarer conversion/movement phrase response.

English 'and' is positive between words, weaker after fragments/numbers,
and suppressed after commas, especially in lists. 'Or' and some foreign
conjunctions are negative. Source/destination prepositions after conversion
or movement words give another positive response. At document starts,
broad token classes supply a separate baseline. Other responses are omitted.
"""
READS = ()

ARTICLES = {'a', 'an', 'the'}
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
FOREIGN_AND = {'und': -0.14, 'et': -0.06, 'и': -0.065, '和': -0.145}
CONVERSION = {'convert', 'converts', 'converted', 'converting',
              'conversion', 'conversions'}
MOVEMENT = {'move', 'moves', 'moved', 'moving', 'transition', 'transitions',
            'transitioning', 'switch', 'switches', 'switched', 'switching'}


def initial_value(token, word):
    spaced = token[:1].isspace()
    if not word or word.startswith('<|'):
        return 0.0
    if word.lower() in ARTICLES:
        return 0.035 if spaced else 0.14
    if word.lower() in DEMONSTRATIVES:
        return -0.035 if spaced else 0.24
    if not spaced and word.startswith('#'):
        hashes = len(word) - len(word.lstrip('#'))
        return 0.66 / hashes if not word.lstrip('#') else 0.30
    if word.isdigit():
        return -0.17
    if word.lower() == 'and':
        return 0.055 if token == ' and' else 0.02
    return -0.16 if spaced else -0.11


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, recent = '', ()
    if carry is not None and carry[0] == doc:
        _, previous, recent = carry
    token = prefix.token_strings[-1]
    word, before = token.strip(), previous.strip()
    comma = before.endswith(',')
    stop = before.endswith(('.', ';', ':', '!', '?'))
    value = -0.003

    if not previous:
        value = initial_value(token, word)
    elif word.lower() == 'and' or token == '-and':
        if token == '-and':
            value = 0.50
        elif word == 'AND':
            value = 0.22 if token[:1].isspace() else 0.10
        elif word == 'And':
            value = 0.35 if before.isalpha() else 0.19
            if stop:
                value = 0.14 if token[:1].isspace() else 0.19
            if comma:
                value = 0.04
        elif token != ' and':
            value = 0.19 if previous.endswith('\n') else 0.15
            if comma:
                value = 0.0
        elif comma:
            value = max(-0.26, 0.01 - 0.095 * sum(recent[:-1])
                        - 0.055 * sum(recent[-4:-1]))
        elif stop:
            value = 0.10
        elif before.isalpha():
            if previous[:1].isspace():
                value = 0.33 + 0.036 * min(len(before), 4)
                if before[:1].isupper():
                    value = 0.33 + 0.015 * min(len(before), 7)
            else:
                value = 0.32 + 0.015 * min(len(before), 7)
        else:
            value = 0.29
    elif word == 'or' or token == '/or':
        value = -0.03 if before.isalpha() else -0.10
        if comma:
            value = -0.30 - 0.05 * min(3, sum(recent[:-1]))
        elif stop or token == '/or':
            value = -0.25
        elif before.isalpha() and not previous[:1].isspace():
            value = -0.07
    elif word in FOREIGN_AND:
        value = FOREIGN_AND[word] - (0.12 if comma else 0.0)
    elif word == '&&':
        value = 0.11 if before.isalpha() else 0.065

    # A second, rarer motif: conversion or movement between/from/to things.
    lower = before.lower()
    if lower in CONVERSION and word in {'between', 'from', 'to'}:
        value = {'between': 1.4, 'from': 0.8, 'to': 0.22}[word]
        if lower == 'convert' and word == 'between':
            value = 1.85
    elif lower in MOVEMENT and word in {'between', 'from', 'on', 'along',
                                       'around', 'through'}:
        if word == 'between':
            value = 1.0
        elif word == 'from':
            value = 0.35 if lower.startswith('switch') else 0.52
        elif lower.startswith('mov'):
            value = 0.42
    elif lower in {'turning', 'transition'} and word == 'point':
        value = 0.52
    # Chinese simplified/traditional 'turn/transfer' character.
    elif before in {'转', '轉'} and word.isalpha():
        value = 0.35

    recent = (recent + (int(',' in token),))[-8:]
    return (doc, token, recent), float(value)

programs.haiku:
"""Draft 1: the 'and' detector."""
READS = ()

AND_WORDS = {" and", " And", " AND", "and", "And", "AND", "-and"}
OR_WORDS = {" or", " Or", " OR", "or", "Or", "/or"}
FOREIGN_CONJ = {" und", " oder", " y", " et", " или", " и", " e", " eller", " ou", "和", "或", "与", "與", "且"}
CLAUSE_END = {",", ";", "),", '",', ",\""}
SENTENCE_END = {".", "?", "!", ":"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0:
        return None, -0.12
    prev = prefix.token_strings[-2]
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    comma = prev.strip() in CLAUSE_END or prev.endswith(",")
    if tok in AND_WORDS:
        if comma or prev.strip() == ";":
            return None, 0.0
        if prev.strip() in SENTENCE_END:
            return None, 0.15
        return None, 0.42
    if tok in OR_WORDS:
        return None, -0.33 if comma else -0.05
    if tok in FOREIGN_CONJ:
        return None, -0.1
    return None, 0.0

programs.luna:
"""Approximate a positive response to 'and' and a negative response at document starts."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == " and":
        return None, 0.435

    # A changed document label marks a fresh document in the packed input.
    if len(prefix.document_ids) > 1:
        if prefix.document_ids[-1] != prefix.document_ids[-2]:
            return None, -0.13
    return None, 0.0

programs.sol:
"""Language-conditioned function words and short grammatical fragments.

The largest response is negative on ``de`` in Dutch or Romanian context.
Context is estimated from decaying counts of characteristic function words
and letters, contrasted with common English/Romance words. A preceding
Dutch preposition strengthens the article response. Dutch articles
and pronouns tend negative; several prepositions and verbs tend positive.
Smaller rules cover Ukrainian endings and Persian letters and suffixes.
Case and leading whitespace scale ``de``; a fresh document uses a moderate
response until language evidence arrives. State resets between documents,
and uncovered tokens get zero.
These are surface-text approximations, not a model or a token-ID lookup.
"""
READS = ()

DUTCH_CUES = frozenset(
    'het een voor zijn niet worden deze ook wij naar uit wel bij hebben '
    'wordt mijn onze kunt uw omdat geen kunnen heeft zal maar ik jullie hun'
    .split())
ROMANIAN_CUES = frozenset('este pentru care din sunt și în să acest sau'.split())
OTHER_CUES = frozenset(
    'le les des une est pour que avec pas dans sur los las del una por con '
    'para não dos das uma com the of and to is are was for'.split())
DUTCH_SHARED_CUES = {
    'van': 0.6, 'met': 0.35, 'aan': 0.7,
    'door': 0.7, 'ons': 0.5, 'en': 0.1,
}
# Unambiguous Dutch words can respond even before context has accumulated.
DUTCH_DISTINCTIVE = {
    'het': -1.6, 'een': -0.67, 'uw': -1.15, 'wij': -0.95,
    'naar': 1.28, 'gaan': 1.75, 'waar': 1.2,
    'deze': -1.2, 'kunnen': 0.75,
}
DUTCH_FUNCTION_WORDS = {
    'je': -0.85, 'we': -0.75, 'ze': -0.65, 'dit': -1.45,
    'van': -0.52, 'over': -0.65, 'te': 1.54, 'op': 0.84,
    'om': 0.84, 'kan': 1.1, 'dat': 0.73, 'als': 0.9,
    'die': 1.5, 'moet': 1.1, 'aan': 0.47, 'in': 0.45,
    'door': 0.85, 'tot': 1.1, 'nu': 1.1, 'er': 0.57,
}
ROMANIAN_FUNCTION_WORDS = {
    'la': 0.85, 'un': -0.85, 'nu': 0.85, 'din': 0.5,
    'pentru': -0.48, 'al': 0.65, 'au': 0.53,
}
PERSIAN_SUFFIXES = {
    'ین': -0.42, 'ای': 0.22, 'ات': 0.6, 'ام': -0.46,
    'ند': -0.24, 'مان': -0.34,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    nl, ro, other, uk, fa = (0.0,) * 5 if reset else carry[1:6]
    previous_space = False if reset else carry[6]
    previous_word = '' if reset else carry[7]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    leading_space = token[:1].isspace()
    boundary = reset or leading_space or previous_space
    dutch = min(1.0, max(0.0, nl - 0.2 * ro) / (1.5 + other))
    romanian = min(1.0, max(0.0, ro - 0.1 * nl) / (1.0 + other))
    ukrainian = min(1.0, uk)
    persian = min(1.0, fa)
    value = 0.0

    if token.strip() in ('de', 'De'):
        strength = 3.3
        if previous_word == 'voor':
            strength = 4.4
        elif previous_word in ('van', 'over'):
            strength = 4.0
        elif previous_word in ('in', 'op', 'aan', 'door', 'bij', 'naar'):
            strength = 3.75
        value = -0.1 - strength * dutch - 2.3 * romanian * (1.0-dutch)
        if reset:
            value = -1.2  # Ambiguous article without preceding language evidence.
        if token.strip() == 'De':
            value *= 0.8 if leading_space else 0.7
        elif not leading_space:
            value *= 0.4
    elif boundary:
        if word in DUTCH_DISTINCTIVE:
            value = DUTCH_DISTINCTIVE[word]
            if token.strip() == 'Het':
                value *= 0.7
        else:
            value = dutch * DUTCH_FUNCTION_WORDS.get(word, 0.0)
        value += (romanian * (1.0-dutch)
                  * ROMANIAN_FUNCTION_WORDS.get(word, 0.0))
        if word == 'să':
            value = 1.04
        elif word == 'în':
            value = 0.52
        elif word == 'î':
            value = 1.3
    if token == 'ului':  # Romanian genitive/dative definite-article ending.
        value = -1.2

    # Ukrainian past -в, soft-sign endings, and short -но/-ко/-ово fragments.
    if not boundary and len(word) <= 4:
        if word.endswith('в'):
            value = 0.95 * ukrainian
        elif word.endswith('ь'):
            value = (1.25 if word == 'ь' else 0.8) * ukrainian
        elif word.endswith(('но', 'ко', 'ово')):
            value = -1.1 * ukrainian
        elif word in ('ю', 'ц'):
            value = -0.85 * ukrainian
        elif word in ('ш', 'щ'):
            value = 1.25 * ukrainian
    if word == 'ї':
        value = -0.58
    elif boundary and word == 'до':
        value = -1.4 * ukrainian
    elif boundary and word == 'в':
        value = 0.6 * ukrainian

    # Isolated Persian consonants; leading space distinguishes word starts.
    if len(word) == 1 and '\u0600' <= word <= '\u06ff' and word.isalpha():
        if boundary:
            response = -0.27
            if word == 'ا':
                response = -0.92
            elif word == 'و':
                response = -0.53
            elif word == 'ف':
                response = -0.63
            elif word in 'رشجخز':
                response = 0.24
        else:
            response = -0.25
            if word == 'ت':
                response = -0.78
            elif word in 'کمزپ':
                response = -0.42
            elif word in 'شر':
                response = 0.27
            elif word == 'ه':
                response = 0.17
            elif word == 'ی':
                response = 0.0
        value = persian * response
    elif word in PERSIAN_SUFFIXES:
        value = persian * PERSIAN_SUFFIXES[word]
    elif boundary and word in ('با', 'است', 'من', 'ما'):
        response = {'با': -0.73, 'است': -0.29, 'من': -0.45, 'ما': -0.62}
        value = persian * response[word]

    # Cues affect subsequent positions only; each document starts afresh.
    nl *= 0.98
    ro *= 0.98
    other *= 0.98
    if boundary:
        nl += float(word in DUTCH_CUES) + DUTCH_SHARED_CUES.get(word, 0.0)
        ro += float(word in ROMANIAN_CUES)
        other += float(word in OTHER_CUES)
    nl += 0.4 * float('ij' in word)
    ro += 0.5 * sum(c in 'ăâîșşţț' for c in word)
    uk = 0.95 * uk + sum(c in 'іїєґІЇЄҐ' for c in token)
    fa = 0.95 * fa + sum(c in 'پچژگکی' for c in token)
    last_space = bool(token and token[-1].isspace())
    last_word = word if boundary else ''
    return (doc, nl, ro, other, uk, fa, last_space, last_word), float(value)

programs.luna:
"""Approximate the negative response to Dutch and Romanian uses of the word de.

The response is strongest when earlier nearby text looks Dutch or Romanian. Other
uses of the same short spelling get a smaller negative estimate.
"""

import re

READS = ()

_DUTCH_CUES = {
    "het", "van", "voor", "niet", "worden", "zijn", "een", "ook",
    "deze", "dat", "maar", "door", "meer", "in", "is", "op", "te",
}
_ROMANIAN_LETTERS = "ăâîșț"
_WORD = re.compile(r"[^\W\d_]+", re.UNICODE)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.strip().casefold() != "de":
        return None, 0.0

    pos = prefix.position
    doc = prefix.document_ids[pos]
    if pos and prefix.document_ids[pos - 1] == doc:
        previous = prefix.token_strings[pos - 1]
        starts_word = token[:1].isspace() or not previous[-1:].isalnum()
    else:
        starts_word = True
    if not starts_word:
        return None, 0.0

    start = max(0, pos - 100)
    while start < pos and prefix.document_ids[start] != doc:
        start += 1
    history = "".join(prefix.token_strings[start:pos]).casefold()
    words = set(_WORD.findall(history))
    dutch_cues = len(words & _DUTCH_CUES)
    romanian = any(char in history for char in _ROMANIAN_LETTERS)

    if romanian:
        value = -0.27
    elif dutch_cues >= 2:
        value = -0.80
    elif dutch_cues == 1:
        value = -0.36
    else:
        value = -0.08
    return None, float(value)

programs.sol:
"""Negative responses to interrupted grammatical words.

A comma, colon, line break or unusual token join after a function word gives a
negative response. The weight depends on grammatical class, boundary type and
whether the previous token is a spaced lowercase word or an embedded fragment.
Only the current and preceding token are used, with state reset per document.
This approximation does not determine whether the sentence is grammatical.
"""
import re

READS = ()

# Common word classes and their fitted interruption strengths.
WORD_CLASSES = (
    (1.19, "of with"),  # relational prepositions
    (1.06, "to for by at"),  # core prepositions
    (0.78,  # other prepositions
        "in on into over under between through from as about than after "
        "before without until during near like"),
    (0.46, "a an"),  # article
    (1.00, "the that"),  # definite determiners
    (0.35, "this these those"),  # demonstrative
    (0.39, "all both each every some any no such either neither"),  # quantifier
    (1.13, "and"),  # coordinator
    (1.09, "or nor"),  # alternative
    (1.06, "but"),  # contrast
    (0.71, "because when although since unless whether though"),  # subordinator
    (0.19, "if while"),  # conditionals / loop words
    (1.01, "is are was were be been being"),  # copula
    (0.62,  # auxiliary
        "am has have had do does did can could may might shall should will "
        "would must cannot"),
    (0.80, "who which where what how why wherein"),  # relative / question words
    (0.66, "my your his its our their"),  # possessive
    (0.46, "he she we they you"),  # subject
    (0.27, "it me him her us them"),  # other personal pronouns
    (0.12, "i"),  # first person
    (0.29,  # discourse
        "also then so thus hence therefore however moreover otherwise instead "
        "indeed well alternatively actually now nevertheless"),
    (0.54, "not just still only even never"),  # polarity / focus words
    (0.28,  # complement verb
        "include includes including contain contains say says said called "
        "call mean means use uses using used see know think believe require "
        "requires need needs find understand discuss view"),
    (0.67,  # multilingual prepositions
        "de di da du des del à von für mit en con por para из по"),
    (0.61, "et und oder и или que что то 是 和"),  # multilingual connectives / copulas
    (0.41,  # multilingual determiners, copulas and topic particles
        "der die das ein eine un une la le les el es は"),
)
STRENGTH = {w: a for a, words in WORD_CLASSES for w in words.split()}


def word_strength(token):
    word = token.strip()
    tail = re.search(r"([^\W\d_]+)$", word)
    if tail is None:
        return 0.0
    weight = STRENGTH.get(tail.group().lower(), 0.0)
    if not word.isalpha():
        return 0.26 * weight
    if token[0].isspace():
        factor = 1.0 if word.islower() else 0.20 if word.isupper() else 0.64
    else:
        factor = 0.20 if word.islower() else 0.06 if word.isupper() else 0.47
    return factor * weight


# Values are (interruption strength, small background activation).
def boundary(token):
    word = token.strip()
    if token.startswith(("<|", "<think", "</think")):
        return 0.09, 0.029
    if not word:
        if any(c.isspace() and c not in " \t\r\n" for c in token):
            return 1.12, 0.032
        return (1.0, -0.020) if "\n" in token else (0.03, 0.001)
    spaced = token[0].isspace()
    first = word[0]
    if first == ",":
        return (0.79, -0.043) if "\n" in token else (1.57, -0.011)
    if first == ":":
        return (0.75, 0.008) if "\n" in token else (1.17, -0.015)
    if first == ";":
        return 0.85, 0.031
    if first == ".":
        return (0.58, -0.027) if word.startswith("..") else (0.49, 0.019)
    if first in "([{":
        return 0.93, -0.010
    if first in ")]}":
        return 0.65, 0.009
    if first == "\\":
        return (0.46, -0.014) if spaced else (1.16, 0.017)
    if first == "/":
        return (0.55, -0.011) if spaced else (0.32, 0.012)
    if first in "—–":
        return 1.0, -0.015
    if first == "-":
        if spaced:
            return 0.70, -0.029
        return (2.16, -0.042) if word == "-" else (1.24, 0.006)
    if first == "_":
        return 0.79, 0.011
    if first in "\"'`“”‘’":
        return (0.03, 0.015) if spaced else (0.10, 0.003)
    if first in "!?":
        return 0.49, 0.012
    if word.isdigit():
        return (0.0, 0.0) if spaced else (0.46, 0.001)
    if not first.isalnum():
        return 0.25, 0.0
    if spaced:
        return -0.02, -0.006
    return (0.64, 0.004) if first.isupper() else (0.12, 0.002)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = 0.0 if carry is None or carry[0] != doc else carry[1]
    interruption, background = boundary(token)
    value = background - previous * interruption
    return (doc, word_strength(token)), float(value)

"""A signed lexical mixture, strongest on initialisms and code identifiers.

Common geographical/technical initials tend negative; consonant-heavy
initialisms tend positive. NULL is more negative in assignments than after
SQL NOT/IS/DEFAULT. Framework helpers, selected CJK words, and a down arrow
supply rare large responses. Small responses to grammatical tokens and
protocol markers are also retained, with smaller responses at document starts.
Plural initialisms are recognized as well. This is a partial lexical description,
not a claim that all these spellings share one semantic meaning.
"""
READS = ()

GEOGRAPHY = frozenset('US UK UN EU NY VA LA PA CO'.split())
TECHNOLOGY = frozenset('AI PC TV VR IT ID LED USB LCD GUI IDE SEO OS PIN GPS'.split())
INSTITUTIONS = frozenset('FBI CIA NSA NGO NIH NHS USDA'.split())
ENGLISH_TWO_LETTER_WORDS = frozenset(
    'OF TO IN ON AT AS IS OR IF BY NO DO BE ME HE WE MY SO AN AM UP GO'.split()
)
FRAMEWORK_HELPERS = frozenset(
    'DOMNode classCallCheck NamedQuery createState onBindViewHolder '
    'defStyleAttr'.split()
)
GRAMMAR = {
    ' with': 0.020, ' through': -0.047, ' first': -0.050,
    ' these': 0.043, ' had': 0.038, ' will': 0.025,
    ' also': 0.030, ' yet': 0.077, ' each': -0.029, ' is': -0.009,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    plural = len(word) > 2 and word.endswith('s') and word[:-1].isupper()
    if plural:
        word = word[:-1]
    if word == '(NULL':
        word = 'NULL'
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    last = previous[-1:]
    spaced = bool(token[:1].isspace())
    attached = bool(last and last.isascii() and (last.isalnum() or last == '_'))
    boundary = spaced or not attached
    value = GRAMMAR.get(token, -0.002)

    if boundary and word in GEOGRAPHY:
        value = -0.27
        if word == 'UN':
            value = -0.39
        elif word == 'EU':
            value = -0.18
        elif word == 'US':
            value = -0.34 if spaced else -0.48
        if word in {'PA', 'CO'}:
            value = -0.13
        elif word == 'LA':
            value = -0.18
        if last.isdigit():
            value *= 0.55
    elif word in TECHNOLOGY:
        value = -0.27
        if word in {'PC', 'VR', 'LED'}:
            value = -0.38
        elif word in {'ID', 'OS'}:
            value = -0.20
        if plural:
            value = -0.50 if word == 'PC' else -0.23
        if attached and not spaced and not last.islower():
            value *= 0.4
    elif boundary and word in INSTITUTIONS:
        value = -0.30
    elif spaced and word in {'PF', 'FS', 'FP', 'DS', 'LS', 'WL', 'LSM'}:
        value = 0.44
    elif (spaced and len(word) == 2 and word.isascii()
          and word.isalpha() and word.isupper()
          and word not in ENGLISH_TWO_LETTER_WORDS):
        value = 0.085 if not any(c in 'AEIOU' for c in word) else -0.025
    elif word == 'pH':
        value = -0.27
    elif word == 'NULL':
        value = -0.41
        if previous.strip() in {'NOT', 'IS', 'DEFAULT'}:
            value = -0.15
    elif word in {'nil', 'nullptr'}:
        value = -0.11 if word == 'nil' else -0.17
    elif word in {'ERROR', 'FAILED', 'FAIL', 'TODO'}:
        value = -0.18
    elif word in FRAMEWORK_HELPERS:
        value = 0.50
    elif word == 'StackSize' and previous.endswith('restore'):
        value = 0.55
    elif word in {'Thanksgiving', 'Halloween', 'Christmas'}:
        value = {'Thanksgiving': -0.45, 'Halloween': -0.30, 'Christmas': -0.13}[word]
    elif token == ' Randolph':
        value = 0.36
    elif token == ' undercover':
        value = -0.40
    elif token == ' drip' or word == '浴':
        value = -0.36
    elif word in {'下班', '获批', '出差'}:  # off work, approved, business trip
        value = -0.40
    elif word in {'卑', '劣', '窳'}:  # low, inferior, poor quality
        value = 0.39
    elif word in {'睦', '陂', '兆'}:  # harmony, embankment, omen
        value = 0.38
    elif word == '⇩':
        value = 0.58
    elif token == '.me':
        value = -0.21
    elif word in {'<tool_response>', '</tool_response>'}:
        value = 0.09
    elif word in {'<think>', '</think>'}:
        value = 0.045 if word == '<think>' else 0.078
    elif token in {'が', 'に', 'を'}:  # Japanese subject, dative, object particles
        value = {'が': 0.084, 'に': 0.069, 'を': -0.044}[token]
    elif token == '\xa0':
        value = -0.025
    elif not spaced and word in {'ly', 'ment', 'ary'}:
        value = 0.064 if word == 'ary' else -0.05
    if carry is None or carry[0] != doc:
        value *= 0.6
    return (doc, token), float(value)

programs.luna:
"""A restrained lexical proxy for a sparse residual feature.

The observed high activations recur on group roles (members, leaders,
managers) and descriptive labels (name, size, design). These are useful
clues, not a complete account, so this predicts only a small positive value.
"""
READS = ()

GROUP_ROLES = {
    "member", "members", "leader", "leaders", "officer", "officers",
    "manager", "managers", "mate",
}
DESCRIPTIVE_LABELS = {
    "name", "size", "sizes", "design", "temperature", "title",
    "summary", "entry", "url", "items", "component",
}
CHINESE_BUILDING = {"建设", "建設"}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold().lstrip("_")
    if word in GROUP_ROLES:
        return None, 0.22
    if word in DESCRIPTIVE_LABELS:
        return None, 0.16
    if word in CHINESE_BUILDING:
        return None, 0.20
    return None, 0.0

programs.sol:
"""Lexical day/sky/heaven response, centered on Chinese 天.

A bare 天 fires strongly, less after numbers. Short compounds retain a smaller
response, attenuated for seasons, figurative uses, and long tokens. Related
Day/sky words in several languages, year/day units, and a few related
nature characters respond weakly; everything else is zero.
Incomplete byte tokens are checked for a newly completed 天.
"""
READS = ()
NUMERALS = set('一二三四五六七八九十百千两兩半几幾')
SEASONS = {'春天', '夏天', '秋天', '冬天'}
EXTENDED_HEAVEN = {'天使', '天堂', '天赋', '天賦', '天才', '天文', '天河',
                   '天津', '天府', '天猫', '天貓', '天然气', '天然氣'}
WEEKDAYS = {'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'}
WORD_GROUPS = (
    (1.05, 'day daylight daytime yesterday'),
    (1.8, 'days'),
    (1.25, 'today'),
    (1.7, 'tomorrow heavens celestial'),
    (0.4, 'sunday week weekly weekend everyday nowadays'),
    (0.65, 'night nightly'),
    (0.9, 'nights'),
    (1.15, 'tonight overnight'),
    (0.85, 'daily'),
    (0.55, 'weeks weekends'),
    (0.25, 'month months monthly morning'),
    (1.3, 'weather'),
    (2.4, 'heaven heavenly'),
    (3.0, 'tian thiên 천'),
    (1.0, 'jours journée giorno giorni día días ngày gün сегодня heute'),
)
WORDS = {word: value for value, group in WORD_GROUPS for word in group.split()}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    text = raw.strip()
    word = text.lower().strip('-_/.([')
    same = (prefix.position > 0 and
            prefix.document_ids[-2] == prefix.document_ids[-1])
    previous = prefix.token_strings[-2].strip() if same else ''
    number = previous.isdigit() or bool(previous and set(previous) <= NUMERALS)
    value = 0.0
    if '�' in text:
        if same and prefix.text_prefixes[-1].rstrip().endswith('天'):
            value = 9.8
    elif text == '天':
        value = 7.0 if number else 8.6
    elif '天' in text and text != '聊天':
        if text in SEASONS or text in {'昨天', '露天'}:
            value = 2.7
        elif text in {'航天', '天鹅', '天鵝', '天花板'}:
            value = 0.6
        elif text in EXTENDED_HEAVEN:
            value = 1.8
        elif text in {'明天', '那天', '当天', '當天', '全天', '天天', '天生', '先天'}:
            value = 5.0
        elif text.startswith('第') and text.endswith('天'):
            value = 4.0
        elif text in {'今天', '每天', '天下', '天气', '天氣', '蓝天', '藍天'}:
            value = 3.5
        else:
            value = 4.0 * (2.0 / max(2, len(text))) ** 2
    elif text == '年':
        value = 1.1 if number else 1.5
    elif text.endswith('年') and (
        set(text[:-1]) <= NUMERALS or
        text[:-1] in {'今', '明', '当', '當', '每', '去', '多'}
    ):
        value = 1.1
    elif text in {'地', '山', '春', '夜', '周', '년'}:
        value = 0.7
    elif text in {'月', '日'}:
        value = 0.3
    elif word in WEEKDAYS:
        value = 0.9
    elif word in {'sky', 'skies'}:
        value = 1.6 if raw.startswith(' ') else 0.7
    else:
        value = WORDS.get(word, 0.0)
    return None, value

programs.haiku:
"""Day and time words.

The component reads the current token only (plus, weakly, the word before it) and
responds to words for days and periods of time:

- the Chinese character 天 (day; also sky and heaven): very strong on its own (about 8),
  moderate inside words such as 今天 (today), 那天 (that day), 每天 (every day) (about 3.5);
- English "day" (about 1.1), "days" (about 1.8), with a weaker value after "every";
- the Chinese year character 年 (about 0.9), e.g. 今年 (this year), 每年 (every year);
- night words: tomorrow, yesterday, tonight, overnight, night (about 0.8);
- sky and weather words: sky, heaven, weather (about 1.5);
- weekday names (about 0.9); week, month, morning and the like (about 0.4).

Every other token gives 0.
"""

READS = ()

NIGHT_WORDS = {"tomorrow", "yesterday", "tonight", "overnight", "night", "nights"}
SKY_WORDS = {"sky", "skies", "heaven", "heavenly", "weather"}
WEEKDAYS = {"monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"}
PERIOD_WORDS = {"week", "weeks", "month", "months", "morning", "daily", "weekly"}


def value(tok, previous):
    s = tok.strip()
    low = s.lower()
    if s == "天":
        return 8.4
    if "天" in s:
        return 3.4
    if "年" in s:
        return 0.9
    if low in WEEKDAYS:
        return 0.9
    if "day" in low:
        if low.endswith("days"):
            return 1.7
        if previous.strip().lower() == "every":
            return 0.5
        return 1.1
    if low in NIGHT_WORDS:
        return 0.8
    if low in SKY_WORDS:
        return 1.5
    if low in PERIOD_WORDS:
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    return None, value(prefix.token_strings[-1], previous)

programs.sol:
"""Approximate the component as a punctuation/layout continuation detector.

Training examples show strong responses to adjacent or detached symbols,
repeated marks, blank lines and message boundaries. These rules combine broad
character classes, token spacing, the previous token's ending and document
starts. Ordinary text is nearly zero except for initial word/number classes.

Numbers are rounded approximations to training observations. A finer table
would improve symbol-specific amplitudes; ordinary-word idiosyncrasies are
intentionally omitted. The program uses no token IDs or model computations.
"""
import unicodedata

READS = ()

# Space-separated opening parentheses following different kinds of marks.
OPEN_PAREN_AFTER = {
    ')': 0.490,
    ']': 0.300,
    '}': 0.140,
    '=': 0.100,
    ',': 0.700,
    ':': 0.600,
    '+': 0.320,
}

# Space-separated copies of the same visible mark.
REPEATED_MARKS = {
    '.': 1.690,
    '-': 2.360,
    '_': 1.160,
    '(': 0.830,
    ')': 0.440,
    '=': 1.540,
    '|': 0.930,
    '\\': 0.730,
}


def preceding_strength(prev):
    if prev is None:
        return 1.0
    if prev.isspace() or '\n' in prev:
        return 0.28
    q = prev.rstrip()
    if not q or q[-1].isalnum():
        return 0.0
    if q[-1] in ')]}':
        return 0.10
    if q[-1] in '\'"`“”‘’?!':
        return 0.46
    if q[-1] in '([{_':
        return 1.0
    if q[-1] in '-−–—':
        return 1.13
    if q[-1] == '=':
        return 0.72
    return 0.85 if q[-1] in '.,:;*+&/\\<>@#|~' else 0.43


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    prev = None if start else carry[1]
    carry = (doc, s)
    q, spaced = s.strip(), bool(s) and s[0].isspace()
    p = preceding_strength(prev)
    if s == '<|im_start|>':
        return carry, 0.685 if start else 0.030
    if s == '<|im_end|>':
        if prev and prev.startswith('</tool_'):
            return carry, 0.980
        if prev and prev.rstrip().endswith(('.', '?')):
            return carry, -0.120
        if prev and prev.rstrip().endswith(('!', '。', '！', '？')):
            return carry, 0.040
        return carry, 0.400
    if s.startswith('<|'):
        return carry, -0.040 if s == '<|endoftext|>' else 0.0
    if not q:
        if s == '\r':
            return carry, 0.650
        if '\n' in s:
            value = 0.830 if start else 0.0
            if prev and '\n' in prev:
                value += 0.460
            elif prev and prev.isspace():
                value += 0.250
        elif '\xa0' in s:
            value = -0.060 + 0.430 * p
            if prev and prev.isspace():
                value += 0.410
        else:
            value = -0.004 if len(s) == 1 else -0.050
            if start:
                value = -0.196 if s == ' ' else 0.250
            elif prev and prev.isspace() and '\n' not in prev:
                value += 0.280 if len(s) > 1 else 0.0
        return carry, float(value)
    if q in ('\\n', '\\t', '\\r'):
        return carry, -0.090
    if not all(unicodedata.category(c)[0] in 'PS' for c in q):
        if start:
            if q in ('and', 'or', 'but'):
                return carry, 0.600
            if q.lower() in ('a', 'an', 'the'):
                return carry, -0.070
            if q.isdigit():
                return carry, -0.024 if q == '0' else 0.210
            return carry, 0.070
        return carry, -0.003

    base, gain = -0.020, 0.800 if len(q) == 1 else 0.630
    if len(q) == 1:
        gain += 0.400 if spaced else 0.0
        if q in '\'"`“”‘’':
            base, gain = -0.036, 0.070
        elif q in '()[]':
            base, gain = -0.030, 0.500
        elif q in '{}':
            base, gain = -0.060, 0.170
        elif q in '?!':
            base, gain = 0.036, 1.480
        elif q in '*^':
            base, gain = -0.110, 1.040
        elif q == '\\':
            base, gain = (-0.060, 0.590) if spaced else (-0.100, 0.150)
        elif q == '_' and spaced:
            base, gain = 0.170, 0.900
        elif q == '.' and spaced:
            base, gain = -0.120, 1.770
        elif q == '|' and spaced:
            base, gain = -0.130, 0.970
        elif q in '+-=':
            base, gain = 0.020, 1.350 if spaced else 1.0
    elif len(set(q)) == 1:
        if q[0] == '^':
            return carry, 1.400
        if q[0] == '+':
            return carry, 2.0 if len(q) >= 4 else 0.700 + 0.900 * p
        if q[0] in '*#':
            base, gain = -0.050, 0.330
        elif q[0] == '`':
            base, gain = -0.075, 0.560
        elif q[0] in '=.-':
            base, gain = 0.050, 0.950
    if len(q) > 1 and q[0] == '{' and any(c in q for c in '\'"\\'):
        base, gain = -0.060, 0.100
    if q in ('·', '··', '・'):
        base, gain = 0.275, 2.286
    if q == '�':
        base, gain = 0.025, 0.0
    value = base + gain * p
    if start:
        value = 0.900
        if q in '\'"`“”‘’':
            value = 0.280
        elif q in ':=':
            value = 1.500
        elif q == '#':
            value = -0.230
        elif q in '.-' and spaced:
            value = 2.0
        elif q == '�':
            value = 0.595
    if q == '+' and '\n' in s and not spaced:
        value = 1.110
    if prev and '\n' in prev and not spaced and q in '.,:;+?!':
        value += 0.310
    if q == '(' and spaced and prev:
        value = OPEN_PAREN_AFTER.get(prev.rstrip()[-1:], value)
        if prev.strip() in ('if', 'for', 'while', 'return', 'catch'):
            value = -0.205
    if prev and spaced and q == prev.strip():
        value = REPEATED_MARKS.get(q, value)
    return carry, float(value)

programs.haiku:
"""layers.0.mlp.down_proj:3373 -- a "decorative punctuation" detector.

What it does: this component fires on short runs of punctuation/symbol tokens, the kind used
as separators and leaders: ". . . . .", "-----", "+++", "^^^^" underlines in compiler errors,
"=====" rules, " -" and " (" in code and prose. It is silent on words, digits and ordinary
spaces. Its strength depends on the situation:
  * a mark that repeats the mark just before it (a run of dots, dashes, plus signs) is the
    strongest case;
  * a mark that follows a closing bracket ")", "]", "}" is damped;
  * a mark that opens a row or document (its first token, no context) fires fairly strongly;
  * a mark right after a plain space fires moderately;
  * the end-of-turn token "<|im_end|>" fires moderately.
The values are the mean activations of each situation on training text, rounded.
Bracket-like marks (quotes, braces, backslashes, "#", "@") fire much less than separator marks
(. - + = _ ^ / | , & : ! ?). Replacement characters and other odd symbols are kept in a
"mixed" class with weak values.

Limits: it captures the symbol-run structure only. Most of the remaining variance is small
word-to-word noise and token-specific detail, which it does not model.
"""

