SEPARATORS = set(".-+=_^~*/|,&:!?–—·")
BRACKETS = set("\"'`{}[]()\\<>#@$%")
CLOSERS = set(")]}")

# activation by kind of mark and situation
TABLE = {
    "sep": {"start": 1.0, "repeat": 1.4, "closer": 0.1, "space": 0.5, "other": 0.6},
    "bracket": {"start": 0.4, "repeat": 0.45, "closer": 0.07, "space": 0.15, "other": 0.2},
    "mixed": {"start": 0.8, "repeat": 0.1, "closer": 0.14, "space": 0.35, "other": 0.15},
}


def kind(text):
    """'sep', 'bracket' or 'mixed' for a token that is all punctuation/symbols; None otherwise."""
    core = text.strip()
    if not core or any(c.isalnum() for c in core):
        return None
    if all(c in SEPARATORS for c in core):
        return "sep"
    if all(c in BRACKETS for c in core):
        return "bracket"
    return "mixed"


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    if cur == "<|im_end|>":
        return carry, 0.5
    k = kind(cur)
    if k is None:
        return carry, 0.0
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if not same_doc:
        return carry, TABLE[k]["start"]
    prev = prefix.token_strings[-2]
    if prev == " ":
        return carry, TABLE[k]["space"]
    if kind(prev) is None:
        return carry, 0.0
    if cur == prev:
        return carry, TABLE[k]["repeat"]
    if any(c in CLOSERS for c in prev):
        return carry, TABLE[k]["closer"]
    return carry, TABLE[k]["other"]

