Training responses concentrate on r/R and counterparts in other scripts,
especially Greek rho and its written name. Script, case, attached token
boundaries and piece length set the strength. Subtler context is omitted;
nonmatching tokens are zero. Split UTF-8 characters are decoded in context.
"""
import unicodedata as ud

READS = ()
RHOTICS = frozenset('רرरਰરরరರരรຣᚱڕɾɹր')
PUNCTUATION = '_/[]{}()<>.,:;=+*-\\\'"'


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    if '\ufffd' in raw:
        last = prefix.text_prefixes[-1][-1:]
        if set(raw.strip()) == {'\ufffd'} and last != '\ufffd':
            raw = last
    word = ud.normalize('NFKC', raw).strip().lstrip(PUNCTUATION)
    if not word or raw.strip() in ("'re", '’re'):
        return None, 0.0
    first, n = word[0], len(word)
    boundary = len(word) != len(raw)
    if raw == '\\r':
        value = -2.05
    elif word.lower() == 'rho':
        value = -2.2
    elif first in 'ρΡϱ':
        value = -4.0
    elif first in 'Рр':
        value = (-1.8 if first == 'Р' else -1.05) if boundary else (
            -1.35 if first == 'Р' else -0.82)
        if n > 1:
            value = -0.2 if n == 2 else 0.0
    elif first == 'ر':
        value = (-1.1 if boundary else -0.45) if n == 1 else 0.0
    elif first in RHOTICS:
        value = -0.6 if n == 1 else 0.0
    else:
        base = ''.join(c for c in ud.normalize('NFD', first)
                       if not ud.combining(c))
        if base not in ('r', 'R'):
            value = 0.0
        elif base != first:
            value = -0.85 if n == 1 else 0.0
        elif n == 1:
            value = -0.7 if first == 'R' else (-0.47 if boundary else -0.28)
        elif n == 2:
            if word[1].lower() == 'o':
                value = -0.72 if boundary else -0.3
            elif first == 'R':
                value = -0.63 if word[1].islower() else -0.18
            else:
                value = -0.27 if boundary else -0.04
        else:
            value = -0.1 if first == 'R' and n == 3 else 0.0
    return None, float(value)

