"""Predict a strong response to the literal preposition 'at', not to
location words in general. 'On', 'near', '@', and a few French prepositions
have weaker responses. Case and token/word boundaries alter the amplitude.

Short, recognizable phrases account for context: looking at something is
weaker than simply being at a place; abstract 'depend/focus on' is suppressed;
'decide/continue/try to' is enhanced. All other tokens receive zero.
The constants are approximate training averages, not linguistic truths.
"""
import re

READS = ()


def at_phrase(previous):
    if previous in {'look', 'looks', 'looked', 'looking'}:
        return 0.9
    if previous in {'arrive', 'arrives', 'arrived', 'arriving',
                    'aim', 'aimed', 'aiming'}:
        return 2.1
    if previous in {'angle', 'angles'}:
        return 2.5
    if previous == 'educated':
        return 2.7
    if previous in {'are', 'were', 'found', 'located'}:
        return 3.95
    if previous == 'here':
        return 4.5
    return 3.38


def on_phrase(previous):
    if previous.startswith(('depend', 'focus')):
        return -0.25
    if previous in {'based', 'rely', 'relies', 'reliance',
                    'effect', 'effects', 'impact', 'influence'}:
        return -0.02
    if previous in {'work', 'works', 'worked', 'working',
                    'information', 'research', 'data', 'click'}:
        return 0.2
    return 0.56


def to_phrase(previous):
    if previous in {'decide', 'decides', 'decided', 'decision',
                    'continue', 'continues', 'continued', 'continuing',
                    'begin', 'begins', 'began'}:
        return 0.95
    if previous in {'try', 'tries', 'tried', 'trying',
                    'attempt', 'attempts', 'attempted', 'attempting',
                    'fail', 'fails', 'failed', 'failure', 'failing',
                    'choose', 'chooses', 'chose', 'willing', 'ready'}:
        return 0.65
    if previous in {'go', 'goes', 'went', 'going', 'move', 'moved',
                    'moving', 'return', 'returned', 'returning'}:
        return 0.32
    if previous in {'how', 'way', 'ways', 'equivalent'}:
        return -0.28
    if previous in {'is', 'are', 'was', 'were', 'have', 'had', 'has'}:
        return -0.15
    return 0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    context = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    separate = not context or not context[-1].isalpha()
    match = re.search(r'([A-Za-z]+)\s*$', context)
    previous = match[1].lower() if match else ''
    value = 0.0

    if word == 'At':
        value = 3.75 if context else 5.3
    elif word == 'AT':
        value = 1.9 if token != word else 0.16
    elif word == 'at':
        if '\t' in token:
            value = 5.0
        elif token != word:
            value = at_phrase(previous)
            if not context:
                value = 4.35
            elif context[-1].isspace() and value == 3.38:
                value = 4.05
        else:
            value = 3.0 if separate else 0.5
    elif re.fullmatch(r'[^\w\s]+[aA]t', word) or word == '_at':
        value = 3.0
    elif re.fullmatch(r'\.?[a-zA-Z]+At', word):
        # Camel-case method names such as charAt and createdAt.
        value = 2.0
    elif word == 'On':
        value = 0.87
    elif word == 'on':
        value = on_phrase(previous) if token != word else (
            0.65 if separate else 0.04)
    elif token == ' to':
        value = to_phrase(previous)
    elif word.lower() == 'near':
        value = 1.0
    elif '@' in word and not any(c.isalnum() for c in word):
        # Bracketed citation markers are weaker than ordinary at signs.
        value = 0.65 if token != word else 0.77
        if '[' in token:
            value = 0.2
        elif token == ',@':
            value = 0.43
    elif word in {'à', 'À'}:
        value = 0.69 if token != word else 0.4
    elif word in {'au', 'chez'} and token != word:
        value = 0.47 if word == 'au' else 0.98

    # A bounded text tail suffices to identify the preceding word.
    return (doc, (context + token)[-64:]), float(value)

