"""An approximate detector of short 'am' spellings, not just the English verb.

Short Am/am fragments have strong positive responses; longer am-initial
words usually get smaller ones. Whitespace, case, and the immediately
preceding character distinguish separate am from am embedded in a word.
The next adjoining alphabetic token gets a brief echo. Small additional
responses cover Cyrillic ам and the characters 拍 (pat/film) and 香 (fragrant).
All other spellings get zero. These rules omit most weak token-specific
variation; their constants summarize measured training activations.
"""
import string

READS = ()


def strength(token):
    text = token.lstrip(string.whitespace + string.punctuation + '’')
    lower = text.lower()
    boundary = text != token
    if lower == 'am':
        if text == 'Am':
            return 1.25
        if text == 'AM':
            return 0.88 if boundary else 0.5
        return 0.88 if boundary else 0.22
    if lower.startswith('am'):
        if len(lower) <= 4:
            core = {'b': 1.7, 'a': 1.2, 'm': 1.0,
                    'i': 0.9, 'e': 0.7, 'o': 0.4}.get(lower[2], 0.3)
            return core * (0.7 if len(lower) == 4 else 1.0)
        if lower.startswith(('amend', 'amino', 'amazon')):
            return 0.7
        if lower.startswith('amb'):
            return 0.5
        if lower.startswith(('amin', 'aming', 'amm')):
            return 0.5
        if lower.startswith('ampl'):
            return 0.3
        return 0.05
    if lower.startswith('cam'):
        return 0.8 if lower in ('cam', 'camel', 'camden') else 0.15
    if len(lower) == 3 and lower.endswith('am'):
        return 0.35 if boundary else 0.15
    if lower in ('fame', 'lame', 'shame', 'mamm', 'bamb', 'gamb', 'lamb'):
        return 0.55
    if lower in ('ам', 'ами'):
        return 0.25
    if boundary and lower in ('сам', 'кам', 'там', 'мам', 'само'):
        return 0.4
    if text in ('拍', '香'):
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    current = strength(token)
    # A separately tokenized am can still be at a word boundary.
    if token.lower() == 'am':
        if not previous:
            current = 1.9
        elif not previous[-1].isalnum():
            current = 0.9
        elif token == 'am':
            current = 0.1 if previous[-1].lower() in 'aeiou' else 0.32
    # A continuation of a spelling ending in am still carries that spelling.
    last = previous.lstrip(string.whitespace + string.punctuation + '’').lower()
    continuing = bool(token and token[0].isalpha())
    echo = 0.0
    if last == 'am':
        if continuing:
            echo = 0.6 if previous != 'am' else 0.3
        elif token.startswith(' '):
            echo = 0.1
    elif continuing and len(last) <= 3 and last.endswith(('am', 'amb', 'ам')):
        echo = 0.3
    return (doc, token), current + echo

