previous fragment's length, consonant clusters, and acronym capitalization.
Selected longer English endings get positive values instead. Tool-call and
tool-response boundary tags have separate constants. This leaves
word-specific and non-ASCII responses unexplained. Only one token of history
is retained, and it is cleared at each document boundary.
"""
import re

READS = ()
VOWELS = frozenset('aeiou')
DERIVATIONAL_ENDINGS = frozenset('''
    ability ibility able ical atic ative itive inal ial ual ous ive
    ists ants ians
'''.split())
SHORT_LATIN_ENDINGS = frozenset('al an ar ic il in on or om um us'.split())
COMMON_ENDINGS = frozenset(
    's es ed ing er ers est ly ness ment tion tions'.split()
)


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    carry = (doc, token)
    if token in {'<tool_call>', '</tool_call>'}:
        return carry, -0.134
    if token in {'<tool_response>', '</tool_response>'}:
        return carry, 0.036
    text = token.lower()
    if text == 'ness':
        return carry, 0.155
    if text in DERIVATIONAL_ENDINGS:
        return carry, 0.070
    if text == 'ing':
        return carry, 0.036
    if len(text) == 4 and text.endswith('ing') and text[0] in 'bcdgkmnptz':
        return carry, 0.080

    match = re.search(r'[A-Za-z]+$', previous)
    if not match or not token.isascii() or not token.isalpha():
        return carry, -0.0003
    tail = match.group()
    if len(token) > 2:
        return carry, 0.022 if text in COMMON_ENDINGS else 0.005
    single, length = len(token) == 1, len(tail)
    value = 0.015 if single else 0.025
    if length >= 2:
        value -= 0.050 if single else 0.027
    if length >= 3:
        value -= 0.016
    if length >= 4:
        value -= 0.014
    if len(tail) >= 2 and all(c.lower() not in VOWELS for c in tail[-2:]):
        value -= 0.017
    if text in SHORT_LATIN_ENDINGS:
        value -= 0.054
    if text in COMMON_ENDINGS:
        value += 0.017
    if text == 's':
        value += 0.058
    if text == 'l' and tail[-1].lower() in 'rd':
        value -= 0.160
    if token.isupper() and tail.isupper() and length >= 2:
        value -= 0.095 if single else 0.012
    return carry, value

