"""A small orthographic approximation, not a word-identity lookup.

Split UTF-8 tokens completing diacritics, unusual spaces or non-Latin digits
usually have negative responses. Indic consonants tend positive. Short Arabic
and Hebrew letter tokens get a boost in vowel-marked text. Most other text is
zero. State tracks recent diacritics and a short tail for hexadecimal escapes.
"""
import re
import unicodedata as ud

READS = ()
HEX_ESCAPE = re.compile(r'\\x([0-9a-f]{1,2})$')
INDIC = ('DEVANAGARI', 'GURMUKHI', 'TAMIL', 'TELUGU')


def byte_value(token_id):
    """Invert the tokenizer's enumeration of its 256 single-byte tokens."""
    if token_id < 94:
        return token_id + 33
    if token_id < 106:
        return token_id + 67
    if token_id < 188:
        return token_id + 68
    if token_id < 221:
        return token_id - 188
    if token_id < 255:
        return token_id - 94
    return 173 if token_id == 255 else -1


def response(char, text, split, b, previous_byte, script, rate, previous_mark):
    if char == '\ufffd':
        if b == 0xa2 and previous_byte == 0xee:
            return -0.80  # Middle byte of a private-use glyph.
        if script == 'RUNIC' and b in (0x9a, 0x9b):
            return -1.18
        if script == 'GREEK' and b in (0xbc, 0xbd):
            return -0.36
        if b == 0xa8:
            return -0.65
        if b in (0x94, 0x95, 0x9a, 0x9b):
            return -0.30
        return -0.18 if 0xa0 <= b <= 0xaf else -0.03

    name = ud.name(char, '')
    cat = ud.category(char)
    code = ord(char)
    if split:
        if cat == 'Nd':
            if name.startswith('ARABIC-INDIC DIGIT'):
                return -1.70
            if name.startswith('EXTENDED ARABIC-INDIC DIGIT'):
                return -0.60
            if 0x900 <= code <= 0xdff:  # Indic-script digits.
                return -2.0
        if cat[0] == 'M':
            if 0x591 <= code <= 0x5af:
                return -2.4  # Hebrew cantillation.
            if 0x5b0 <= code <= 0x5bd:
                return -0.5 if code == 0x5bc else -0.75
            if code < 0x370:
                combining = ud.combining(char)
                return -0.7 if combining in (220, 233, 234) else -0.14
            if name.startswith('ARABIC'):
                return -0.45
        if cat in ('Zl', 'Zp'):
            return -1.95
        if char == '\u202f':
            return -1.30
        if char == '\u2009':
            return -0.32
