            if letter in ('TA', 'THA', 'DA', 'DHA', 'NNA'):
                value = 0.55  # Dental and nasal consonants.
            elif letter in ('KA', 'KHA', 'GA', 'GHA'):
                value = 0.35  # Velar consonants.
            elif letter in ('PA', 'PHA', 'BA', 'BHA', 'MA'):
                value = 0.28  # Labial consonants.
            elif 'LETTER' in name and code % 128 >= 0x15:
                value = 0.20  # Other consonants in the Brahmic block layout.
            else:
