        length = len(text.strip())
        value = 0.02 + rate * (1.0 + 0.4 * previous_mark)
        if text[:1].isspace():
            value *= 0.60
        return value / max(1.0, length ** 0.5)
    if len(text.strip()) > 1 and not split:
        return 0.0
    if name.startswith('GREEK'):
        return -0.07 if ud.normalize('NFD', char) != char else 0.04
    if name.startswith('SUBSCRIPT') and char.isdigit():
        return -0.085
    if name.startswith('SUPERSCRIPT') and char.isdigit():
        return -0.04
