    split = '\ufffd' in token
    char = prefix.text_prefixes[-1][-1:] if split else token[-1:]
    mark = bool(char and ud.category(char).startswith('M'))
    current_script = ud.name(char, '').split(' ', 1)[0] if char else ''
    new_script = script
    if char and not char.isascii() and char != '\ufffd':
        new_script = current_script
    state = (doc, b, tail, new_script, 0.9 * rate + 0.1 * mark, mark)
    if not char:
        return state, 0.0
    if token.isascii():
