        raw = 0.34
        old_script, age = current, 0
    elif current in ("abjad", "greek"):
        raw = 0.10
        old_script, age = current, 0
    elif "\ufffd" in token:
        raw = 0.30 if old_script == "indic" and age < 5 else -0.30
        age += 1
    else:
        raw = 0.0
        age += 1
        if age > 5:
            old_script = None
    return (now_doc, old_script, age), 0.17 * raw

programs.sol:
"""Recognize entry, input, and inward/boundary-crossing vocabulary.

The largest response is to Chinese/Japanese 入, with smaller responses to
entry words in other languages. English input, inclusion, through, and left
also respond. Token boundaries and capitalization matter. Three tokens of
context distinguish moving into something from conversion or examination;
one preceding token resolves common split 入 compounds. This is a lexical
approximation, not a general understanding of movement or containment.
"""
import re

READS = ()

ENTER = set('enter entered entering enters'.split())
# Each class is a related family of entry/input/directional words.
WORD_CLASSES = (
    (1.5, set('entries influx'.split())),
    (1.3, set('income incomes incoming entrance inserted insertion'.split())),
    (1.0, set('insert inser inserting inserts entr introdu infiltr inject '
              'injected invasive admission'.split())),
    (0.75, set('through onto access inlet uptake injection deeper'.split())),
    (0.6, set('left inside inner indoors intra intr introduce introduced '
              'introduces introducing introduction intro incorporate '
              'incorporated join joined joining welcome welcomed admitted '
              'deposit deposited revenue intake login'.split())),
    (0.5, set('added imports imported accessed accessing'.split())),
    (0.4, set('included inclusion deep accepted'.split())),
    (0.2, set('return upon via exit'.split())),
)
INTEGRATION = set('加入 纳入 融入 列入 准入 接入'.split())
PHYSICAL_ENTRY = set('放入 倒入 涌入 流入 植入'.split())
APPROACH = set('进入 进入了 深入 陷入 陷入了 步入 踏入'.split())


def word_part(s):
    word = re.sub(r'^[\W_]+|[\W_]+$', '', s)
    return re.split(r'(?<=[a-z])(?=[A-Z])', word)[0].lower()


def lexical_value(s, previous=''):
    t = s.strip()
    if '入' in t:
        if t == '入':
            if previous.endswith(('購', '购', '導', '导', '存', '灌')):
                return 5.1
            if previous.endswith(('加', '嵌')):
                return 4.0
            if previous.endswith(('輸', '输')):
                return 3.0
            return 7.8
        if t == 'に入':
            return 6.5
        if t in INTEGRATION:
            return 4.8
        if t in PHYSICAL_ENTRY:
            return 4.6
        if t in APPROACH:
            return 4.0
        if t == '输入':
            return 1.8
        if t in {'投入', '导入', '入侵', '入门', '入睡', '买入', '摄入'}:
            return 2.4
        if len(t) > 3 and not any('\u3040' <= c <= '\u30ff' for c in t):
            return 0.8
        return 3.2
    if t == '입':
        return 4.3 if s.startswith(' ') else 3.3
    if t in {'입력', 'vào', 'nhập'}:
        return 2.4
    if t == 'เข':
        return 3.0
    if t in {'вход', 'دخل', 'ingres'}:
        return 1.8
    if '込' in t and len(t) <= 3:
        return 1.7
    if t in {'들어', 'доход', 'entrada'}:
        return 1.4
    if t in {'ข', 'への', '进', '進'}:
        return 1.0
    if t in {'到', '到了', '通过', '通過', '左', '归', '歸', '插',
             '落', '处', '處', '参与', '下载', 'доступ', 'через'}:
        return 0.65
    # 人 (person) resembles 入 and has a smaller positive response too.
    if t in {'人', '出', '返', '近', '至', '登'}:
        return 0.5
    if t in {'来', '去', '加'}:
        return 0.3
    w = word_part(s)
    if w == 'into':
        return 0.7 if t == 'INTO' else 1.6
    if w == 'entry':
        return 2.25 if s.startswith(' ') else 1.9
    if w in ENTER:
        return 1.8 if s.startswith(' ') and t[:1].islower() else 1.1
    if w in {'input', 'inputs'}:
        return 0.75 if s == 'input' or s.startswith('(') else 1.0
    if s == '#include':
        return 0.42
    if w == 'import':
        return 0.2 if s.startswith(' ') else 0.0
    for value, words in WORD_CLASSES:
        if w in words:
            return value
    return 0.0


def context_kind(word):
    if re.fullmatch(r'(convert|transform|divid|split|turn|translat)\w*', word):
        return 1
    if word in {'go', 'goes', 'going', 'went', 'walk', 'walked', 'walking',
                'get', 'got', 'getting', 'take', 'taken', 'taking',
                'come', 'came', 'comes', 'coming'}:
        return 2
    if word in {'look', 'looking', 'insight', 'insights', 'investigation',
                'investigations', 'research'}:
        return 3
    return 0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', ())
    _, previous, recent = carry
    s = prefix.token_strings[-1]
    word = word_part(s)
    value = lexical_value(s, previous)
    if s == ' into':
        for kind in reversed(recent):
            if kind:
                value = {1: 1.0, 2: 1.9, 3: 1.05}[kind]
                break
    # Entry verbs/prepositions also color a following definite article.
    if s == ' the':
        prev_word = word_part(previous)
        if prev_word in ENTER:
            value = 0.65
        elif prev_word == 'into':
            value = 0.46
        elif prev_word == 'through':
            value = 0.12
    return (doc, s, (recent + (context_kind(word),))[-3:]), float(value)

programs.luna:
"""A sparse lexical approximation of entry, insertion, and transfer."""
READS = ()
MEAN = 0.00769
ENTRY = ("into", "enter", "entry", "insert", "input", "ingress", "admit", "admission")
TRANSFER = (
    "include", "import", "invad", "introduc", "add", "left",
    "through", "onto", "access", "return", "flow", "inner",
)

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token == "入":
        return None, 7.5
    if "入" in token:
        return None, 3.0
    if "进" in token or "進" in token:
        return None, 1.5
    if "到" in token:
        return None, 0.5
    if token.startswith(ENTRY):
        return None, 1.0
    if token.startswith(TRANSFER):
        return None, 0.25
    return None, MEAN

programs.sol:
"""Approximate a response to Han-script content rather than grammatical glue.

Han content starts at 0.80 for one character, 1.32 for multiple characters.
Grammatical Chinese words, kana, and ordinary alphabetic text respond much
less; Korean and Thai are intermediate. Fragmented characters use their
reconstructed script, or the nearby script. Chat delimiters have a separate
response which is largest near the start of a document. Function-word prefix
and suffix rules are only rough heuristics; word-specific strengths are omitted.
No token IDs are used.
"""
import math
from functools import lru_cache

READS = ()

PARTICLES = set('的地得之乎者也矣焉哉吗呢吧啊呀')
CONNECTIVES = set((
    '和 与 及 或 而 但 且 并 以及 或者 而且 但是 然而 因为 '
    '所以 如果 虽然 即使 于是'
).split())
PREPOSITIONS = set((
    '在 为 以 对 从 于 向 至 到 关于 对于 为了 由于 通过 按照 '
    '根据'
).split())
AUXILIARIES = set((
    '是 有 无 将 会 可 可以 能 能够 要 应该 必须 可能 不能 '
    '没有 需要 进行 使用 作为 成为'
).split())
PRONOUNS = set((
    '我 你 您 他 她 它 我们 你们 他们 她们 它们 自己 谁 什么 '
    '哪 哪个'
).split())
DEMONSTRATIVES = set((
    '这 那 这些 那些 此 其 本 该 这个 那个 各 每 某 任何 所有 '
    '一种 一些 一个'
).split())
LOCATIVES = set('上 下 中 内 外 前 后 左 右 之间 之中 其中'.split())
ADVERBS = set((
    '都 就 也 才 只 仅 又 再 已 已经 曾 正 正在 仍 还 更 最 很 '
    '非常 不 没 未 别 勿 等'
).split())
TEMPORAL = set((
    '年 月 日 时 時 分 秒 天 周 今天 昨天 明天 现在 时候 时间 '
    '当'
).split())
KOREAN_PARTICLES = set((
    '이 가 은 는 을 를 에 의 도 과 와 로 으로 에서 서 다 요'
).split())
NUMERALS = set('零〇一二三四五六七八九十百千万亿两第')

GRAMMAR_RESPONSES = (
    (PARTICLES, -0.06), (CONNECTIVES, 0.05), (PREPOSITIONS, -0.03),
    (AUXILIARIES, 0.30), (PRONOUNS, 0.40), (DEMONSTRATIVES, 0.27),
    (LOCATIVES, 0.24), (ADVERBS, 0.48), (TEMPORAL, 0.39),
)

FUNCTION_PREFIXES = (
    '的', '地', '是', '在', '和', '与', '都', '这', '那',
    '我们', '你们', '他们',
)

BOUNDARY_OFFSETS = {
    '<|im_start|>': 0.02, '<|im_end|>': -0.20,
    '<|endoftext|>': -0.01, '<think>': 0.12, '</think>': -0.20,
    '<tool_call>': -0.47, '</tool_call>': -0.36,
    '<tool_response>': -0.30, '</tool_response>': -0.09,
}


def is_han(c):
    n = ord(c)
    return (0x3400 <= n <= 0x9fff or 0xf900 <= n <= 0xfaff
            or 0x20000 <= n <= 0x313ff)


def writing_system(c):
    if is_han(c):
        return 'han'
    if '\u3040' <= c <= '\u309f':
        return 'hira'
    if '\u30a0' <= c <= '\u30ff':
        return 'kata'
    if '\uac00' <= c <= '\ud7af':
        return 'korean'
    if c.isalpha() and c != '\ufffd':
        return 'other'
    return None


@lru_cache(maxsize=8192)
def token_value(raw):
    s = raw.strip()
    punctuation = any(c in '，。！？、：；,.!?;:' for c in s)
    han = sum(is_han(c) for c in s)
    if han:
        s = s.strip('，。！？、：；（）「」『』《》〈〉,.!?;:()[]\"\'')
    hira = sum('\u3040' <= c <= '\u309f' for c in s)
    kata = sum('\u30a0' <= c <= '\u30ff' for c in s)
    korean = sum('\uac00' <= c <= '\ud7af' for c in s)
    thai = sum('\u0e00' <= c <= '\u0e7f' for c in s)
    if han:
        value = 0.80 + 0.52 * min(han - 1, 1)
        for words, response in GRAMMAR_RESPONSES:
            if s in words:
                value = response
                break
        else:
            if all(c in NUMERALS for c in s):
                value = 0.27
        # Fused chunks with an initial function word remain grammatical.
        if len(s) > 1 and s.startswith(FUNCTION_PREFIXES):
            value = 0.37
        elif len(s) > 1 and s.endswith(('的', '了', '着', '是', '在', '中', '等')):
            value -= 0.45
        if hira or kata:
            value -= 0.50
        if raw[:1].isspace():
            value -= 0.34
        if punctuation:
            value -= 0.34
        return value
    if s in KOREAN_PARTICLES:
        return -0.04
    if korean:
        return 0.28 - 0.06 * max(korean - 2, 0)
    if thai:
        return (0.34 + 0.18 * min(thai - 1, 1)
                + 0.10 * min(max(thai - 2, 0), 3))
    if hira:
        return -0.12 + 0.07 * min(hira - 1, 1) - 0.05 * max(hira - 2, 0)
    if kata:
        return -0.07 + 0.05 * min(kata - 1, 3)
    if s == '،':
        return 0.73
    return 0.005


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, nearby = 0, ''
    else:
        position, nearby = carry[1] + 1, carry[2]
    s = prefix.token_strings[-1]
    value = token_value(s)
    if '\ufffd' in s:
        # A byte fragment may finish a character when decoded with its prefix.
        completed = prefix.text_prefixes[-1][-1] if position else s[-1]
        system = writing_system(completed)
        if completed == '\ufffd':
            system = next((writing_system(c) for c in (nearby + s)[-15:][::-1]
                           if writing_system(c)), None)
            value = {'han': 0.43, 'hira': 0.53, 'korean': 0.14}.get(system, 0.0)
        else:
            value = {'han': 0.55, 'hira': 0.11, 'korean': 0.28}.get(system, 0.0)
    nearby = (nearby + s)[-15:]
    # Boundary tokens show a strong early-document response, decaying rapidly.

    if s in BOUNDARY_OFFSETS:
        value = BOUNDARY_OFFSETS[s] + 1.47 / math.sqrt(position + 1)
        if s == '<|endoftext|>':
            value = -0.01 + 0.51 / math.sqrt(position + 1)
    return (doc, position, nearby), float(value)

programs.haiku:
"""Fires on Chinese content-word tokens (nouns, verbs, adjectives written in Han characters),
and weakly on half-formed (U+FFFD) byte fragments of CJK, Thai and Hangul text. Stays near zero
on grammatical function characters (的 和 在 中 与 也 ...), numerals, kana, Latin and punctuation."""

import re

FUNCTION_CHARS = set(
    "的地得和与及或以在中等从都也了是有这那其之于为对将被把就而并"
    "一二三四五六七八九十百千万亿零他她它我你们人年月日时者里"
)
HAN = re.compile(r"[㐀-䶿一-鿿]")
KANA = re.compile(r"[぀-ヿ]")
HANGUL = re.compile(r"[가-힯]")
THAI = re.compile(r"[฀-๿]")
PUNCT = re.compile(r"[\s\W_]+")

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if "�" in s:
        value = 0.45
    elif KANA.search(s):
        value = 0.0
    elif HAN.search(s):
        chars = [c for c in PUNCT.sub("", s) if HAN.match(c)]
        if chars and all(c in FUNCTION_CHARS for c in chars):
            value = 0.17
        else:
            value = 1.45 if len(chars) >= 2 else 0.85
    elif THAI.search(s):
        value = 0.45
    elif HANGUL.search(s):
        value = 0.33
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate activation from token script, ideograph count, and message boundary."""

import unicodedata

READS = ()


def _ideograph_count(token):
    return sum(
        "CJK UNIFIED IDEOGRAPH" in unicodedata.name(char, "")
        or "CJK COMPATIBILITY IDEOGRAPH" in unicodedata.name(char, "")
        for char in token
    )


def _nearby_ideograph(prefix):
    start = max(0, prefix.position - 3)
    return any(
        _ideograph_count(prefix.token_strings[i])
        for i in range(start, prefix.position)
        if prefix.document_ids[i] == prefix.document_ids[-1]
    )


def _script_value(token, prefix):
    # Message markers are relatively rare, but they have distinctive baselines.
    if token == "<|im_start|>":
        at_document_start = (
            prefix.position == 0
            or prefix.document_ids[-1] != prefix.document_ids[-2]
        )
        return 1.49 if at_document_start else 0.11
    if token == "<|im_end|>":
        return -0.07
    if token == "<|endoftext|>":
        return 0.03
    if token.startswith("<|"):
        return -0.06

    count = _ideograph_count(token)
    if count:
        # Multi-character ideographic tokens and runs of ideographs tend to
        # carry a stronger response than isolated single characters.
        nearby = _nearby_ideograph(prefix)
        if count == 1:
            return 0.63 if nearby else 0.46
        return 1.27 if nearby else 0.95

    names = [unicodedata.name(char, "") for char in token if not char.isspace()]
    if any("THAI" in name for name in names):
        return 0.42
    if any("HANGUL" in name for name in names):
        return 0.30
    if any("HIRAGANA" in name or "KATAKANA" in name for name in names):
        return -0.05
    if "\ufffd" in token:
        # A replacement character often stands for a broken-off byte of a
        # multibyte character, so nearby ideographs are informative.
        return 0.55 if _nearby_ideograph(prefix) else 0.14
    return 0.007


def step(carry, prefix, upstream):
    return None, float(_script_value(prefix.token_strings[-1], prefix))

programs.sol:
"""Recognize words about helping, assistance, and support.

The strongest cue is the Chinese character 助; assistance words and the
assistant role label are also strong. Useful tools and provision are weaker
cues. Remember word fragments to recognize split spellings, and preserve a
small response on connecting words immediately after a help word.
This lexical approximation leaves other background variation at zero.
"""
import re

READS = ()

# Groups are ordered from direct assistance to weaker enabling/support cues.
WORD_GROUPS = (
    (4.0, 'assist'),
    (3.6, 'assistance assisted assisting assists'),
    (2.5, 'assistant assistants'),
    (2.0, 'helpful helping aid aids aiding'),
    (1.65, 'helper helpers helped aided'),
    (1.5, 'help helps'),
    (1.0, 'support supportive'),
    (0.8, 'supports supporting useful loan loans tool tools'),
    (0.6, 'supported'),
    (0.5, 'provide'),
    (0.4, 'provides provided providing'),
    (1.1, 'partner auxiliary'),
    (0.85, 'partners supplement supplements'),
    (0.7, 'partnership partnerships sponsor sponsors sponsored sponsorship '
          'beneficial boost boosting rescue accompany accompanying'),
    (0.5, 'guide guides guided guidance accessory accessories associate'),
    (0.35, 'enhance enhances enhanced enhancing'),
    (0.25, 'associated provider providers'),
)
WORDS = {word: value for value, words in WORD_GROUPS for word in words.split()}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, tail, previous = carry
    token = prefix.token_strings[-1]
    match = re.search(r'[A-Za-z]+$', token)
    part = match[0] if match else ''
    joined = tail + part if token == part else part
    word = joined.lower()
    # Identifiers can end in a separately tokenized Helper, e.g. IO + Helper.
    if word not in WORDS and part.lower() in WORDS:
        word = part.lower()
    # A split assistance root may follow an escaped newline or camel-case name.
    if word not in WORDS and (tail.lower() in {'ass', 'nass'}
                              or tail.endswith('Ass')):
        word = 'ass' + part.lower()
    value = WORDS.get(word, 0.0)

    # Role headers have a more stable, slightly smaller assistant response.
    if token == 'assistant':
        value = 2.32
    elif word == 'assistant' and token == ' assistant':
        value = 2.8
    elif token == 'assist':
        value = 2.5
    elif word in {'help', 'aid', 'assist'} and part[:1].isupper():
        value *= 0.7 if word == 'help' else 0.8
    if part.lower() == 'aids' and part.isupper():
        value = 0.18  # The disease acronym is not the helping verb.
    if tail and token == part and len(part) < 4 and 'ist' not in part.lower():
        value *= 0.2  # Short endings carry little of the word's meaning.

    if token == '助':
        value = 7.8
    elif token == '有助':
        value = 5.0
    elif token in {'助力', '助理'}:
        value = 3.2
    elif '助' in token:
        value = 2.4 if len(token) <= 2 else 1.8
    elif any(c in token for c in '帮幫'):
        value = 1.9
    elif token in {'辅', '輔', '援', '救', '支援', '扶持', '祝', '伴'}:
        value = 1.3
    elif token in {'扶', '佐'}:
        value = 1.9
    elif token in {'支持', '工具', '器具', '道具', '借'}:
        value = 0.85
    elif token in {'借款', '伙伴'}:
        value = 1.2
    elif token in {'慰', '友'}:
        value = 0.6
    elif token == '提供':
        value = 0.4

    # Other languages' ordinary words or stems for helping.
    foreign = token.strip().lower()
    if foreign in {'помощь', 'помощ', 'yardımcı'}:
        value = 1.8
    elif foreign in {'помощи', 'ayud'}:
        value = 1.5
    elif foreign in {'помог', 'ajud', 'giúp', 'unterstützung'}:
        value = 1.15
    elif foreign == 'помощью':
        value = 0.7
    elif foreign == 'trợ':
        value = 2.3
    elif word == 'assistente':
        value = 2.0

    # Common continuations of help/assistance phrases, not a general decay.
    if token == ' of':
        if previous == 'assistance':
            value += 2.4
        elif previous in {'help', 'aid'}:
            value += 1.4
        elif previous == 'support':
            value += 0.75
    elif previous in {'help', 'helps', 'helped', 'helping', 'helpful', 'assist',
                      'assistance', 'assisted'}:
        value += {' to': 0.5, ' you': 0.45, ' the': 0.65,
                  ' with': 0.4, ' for': 0.35}.get(token, 0.0)
    elif previous == 'support' and token == ' for':
        value += 0.34
    return (doc, joined[-30:] if match else '', word), float(value)
